(window.QDATA=window.QDATA||{})[26]={"s":26,"ar":"الشعراء","tl":"Ash-Shu'ara","n":227,"place":"makkah","bism":true,"mean":{"en":"The Poets","ur":"شعراٗ","hi":"कवि"},"v":[{"a":1,"ar":" طسٓمٓ","en":"Ṭā, Seen, Meem.","ur":"طٰسٓمٓ","hi":"ता, सीन, मीम।"},{"a":2,"ar":"تِلْكَ ءَايَـٰتُ ٱلْكِتَـٰبِ ٱلْمُبِينِ","en":"These are the verses of the clear Book.","ur":"یہ کتاب روشن کی آیتیں ہیں","hi":"ये स्पष्ट किताब की आयतें हैं।"},{"a":3,"ar":"لَعَلَّكَ بَـٰخِعٌ نَّفْسَكَ أَلَّا يَكُونُوا۟ مُؤْمِنِينَ","en":"Perhaps, [O Muḥammad], you would kill yourself with grief that they will not be believers.","ur":"(اے پیغمبرﷺ) شاید تم اس (رنج) سے کہ یہ لوگ ایمان نہیں لاتے اپنے تئیں ہلاک کردو گے","hi":"शायद (ऐ रसूल!) आप अपने आपको हलाक करने वाले हैं, इसलिए कि वे ईमान नहीं लाते।"},{"a":4,"ar":"إِن نَّشَأْ نُنَزِّلْ عَلَيْهِم مِّنَ ٱلسَّمَآءِ ءَايَةً فَظَلَّتْ أَعْنَـٰقُهُمْ لَهَا خَـٰضِعِينَ","en":"If We willed, We could send down to them from the sky a sign for which their necks would remain humbled.","ur":"اگر ہم چاہیں تو ان پر آسمان سے نشانی اُتار دیں۔ پھر ان کی گردنیں اس کے آگے جھک جائیں","hi":"यदि हम चाहें, तो उनपर आकाश से कोई निशानी उतार दें, फिर उसके सामने उनकी गर्दनें झुकी रह जाएँ।"},{"a":5,"ar":"وَمَا يَأْتِيهِم مِّن ذِكْرٍ مِّنَ ٱلرَّحْمَـٰنِ مُحْدَثٍ إِلَّا كَانُوا۟ عَنْهُ مُعْرِضِينَ","en":"And no mention [i.e., revelation] comes to them anew from the Most Merciful except that they turn away from it.","ur":"اور ان کے پاس (خدائے) رحمٰن کی طرف سے کوئی نصیحت نہیں آتی مگر یہ اس سے منہ پھیر لیتے ہیں","hi":"और जब भी 'रह़मान' (अति दयावान्) की ओर से उनके पास कोई नई नसीहत आती है, तो वे उससे मुँह फेरने वाले होते हैं।"},{"a":6,"ar":"فَقَدْ كَذَّبُوا۟ فَسَيَأْتِيهِمْ أَنۢبَـٰٓؤُا۟ مَا كَانُوا۟ بِهِۦ يَسْتَهْزِءُونَ","en":"For they have already denied, but there will come to them the news of that which they used to ridicule.","ur":"سو یہ تو جھٹلا چکے اب ان کو اس چیز کی حقیقت معلوم ہوگی جس کی ہنسی اُڑاتے تھے","hi":"अतः निःसंदेह उन्होंने झुठला दिया, तो शीघ्र ही उनके पास उस चीज़ की खबरें आ जाएँगी, जिसका वे उपहास उड़ाया करते थे।"},{"a":7,"ar":"أَوَلَمْ يَرَوْا۟ إِلَى ٱلْأَرْضِ كَمْ أَنۢبَتْنَا فِيهَا مِن كُلِّ زَوْجٍ كَرِيمٍ","en":"Did they not look at the earth - how much We have produced therein from every noble kind?","ur":"کیا انہوں نے زمین کی طرف نہیں دیکھا کہ ہم نے اس میں ہر قسم کی کتنی نفیس چیزیں اُگائی ہیں","hi":"और क्या उन्होंने धरती की ओर नहीं देखा कि हमने उसमें हर उत्तम प्रकार के कितने पौधे उगाए हैं?"},{"a":8,"ar":"إِنَّ فِى ذَٰلِكَ لَـَٔايَةً ۖ وَمَا كَانَ أَكْثَرُهُم مُّؤْمِنِينَ","en":"Indeed in that is a sign, but most of them were not to be believers.","ur":"کچھ شک نہیں کہ اس میں (قدرت خدا کی) نشانی ہے مگر یہ اکثر ایمان لانے والے نہیں ہیں","hi":"निःसंदे इसमें निश्चय एक बड़ी निशानी है। (परंतु) उनमें से अधिकतर ईमान लाने वाले नहीं थे।"},{"a":9,"ar":"وَإِنَّ رَبَّكَ لَهُوَ ٱلْعَزِيزُ ٱلرَّحِيمُ","en":"And indeed, your Lord - He is the Exalted in Might, the Merciful.","ur":"اور تمہارا پروردگار غالب (اور) مہربان ہے","hi":"तथा निःसंदेह आपका पालनहार, निश्चय वही सबपर प्रभुत्वशाली, अत्यंत दयावान् है।"},{"a":10,"ar":"وَإِذْ نَادَىٰ رَبُّكَ مُوسَىٰٓ أَنِ ٱئْتِ ٱلْقَوْمَ ٱلظَّـٰلِمِينَ","en":"And [mention] when your Lord called Moses, [saying], \"Go to the wrongdoing people -","ur":"اور جب تمہارے پروردگار نے موسیٰ کو پکارا کہ ظالم لوگوں کے پاس جاؤ","hi":"और जब आपके पालनहार ने मूसा को पुकारा कि उन ज़ालिम लोगों के पास जाओ।"},{"a":11,"ar":"قَوْمَ فِرْعَوْنَ ۚ أَلَا يَتَّقُونَ","en":"The people of Pharaoh. Will they not fear Allāh?\"","ur":"(یعنی) قوم فرعون کے پاس، کیا یہ ڈرتے نہیں","hi":"फ़िरऔन की जाति के पास। क्या वे डरते नहीं?"},{"a":12,"ar":"قَالَ رَبِّ إِنِّىٓ أَخَافُ أَن يُكَذِّبُونِ","en":"He said, \"My Lord, indeed I fear that they will deny me","ur":"انہوں نے کہا کہ میرے پروردگار میں ڈرتا ہوں کہ یہ مجھے جھوٹا سمجھیں","hi":"उसने कहा : ऐ मेरे पालनहार! निःसंदेह मुझे डर है कि वे मुझे झुठला देंगे।"},{"a":13,"ar":"وَيَضِيقُ صَدْرِى وَلَا يَنطَلِقُ لِسَانِى فَأَرْسِلْ إِلَىٰ هَـٰرُونَ","en":"And that my breast will tighten and my tongue will not be fluent, so send for Aaron.","ur":"اور میرا دل تنگ ہوتا ہے اور میری زبان رکتی ہے تو ہارون کو حکم بھیج کہ میرے ساتھ چلیں","hi":"और मेरा सीना घुटता है और मेरी ज़बान नहीं चलती, अतः हारून की ओर संदेश भेज।"},{"a":14,"ar":"وَلَهُمْ عَلَىَّ ذَنۢبٌ فَأَخَافُ أَن يَقْتُلُونِ","en":"And they have upon me a [claim due to] sin, so I fear that they will kill me.\"","ur":"اور ان لوگوں کا مجھ پر ایک گناہ (یعنی قبطی کے خون کا دعویٰ) بھی ہے سو مجھے یہ بھی خوف ہے کہ مجھ کو مار ہی ڈالیں","hi":"और उनका मुझपर एक अपराध का आरोप है। अतः मैं डरता हूँ कि वे मुझे मार डालेंगे।"},{"a":15,"ar":"قَالَ كَلَّا ۖ فَٱذْهَبَا بِـَٔايَـٰتِنَآ ۖ إِنَّا مَعَكُم مُّسْتَمِعُونَ","en":"[Allāh] said, \"No. Go both of you with Our signs; indeed, We are with you, listening.","ur":"فرمایا ہرگز نہیں۔ تم دونوں ہماری نشانیاں لے کر جاؤ ہم تمہارے ساتھ سننے والے ہیں","hi":"(अल्लाह ने) फरमाया : ऐसा कभी नहीं होगा, अतः तुम दोनों हमारी निशानियों के साथ जाओ। निःसंदेह हम तुम्हारे साथ ख़ूब सुनने वाले हैं।"},{"a":16,"ar":"فَأْتِيَا فِرْعَوْنَ فَقُولَآ إِنَّا رَسُولُ رَبِّ ٱلْعَـٰلَمِينَ","en":"Go to Pharaoh and say, 'We are the messengers of the Lord of the worlds,","ur":"تو دونوں فرعون کے پاس جاؤ اور کہو کہ ہم تمام جہان کے مالک کے بھیجے ہوئے ہیں","hi":"तो तुम दोनों फ़िरऔन के पास जाओ और कहो कि निःसंदेह हम सारे संसारों के पालनहार के संदेशवाहक हैं।"},{"a":17,"ar":"أَنْ أَرْسِلْ مَعَنَا بَنِىٓ إِسْرَٰٓءِيلَ","en":"[Commanded to say], \"Send with us the Children of Israel.\"'\"","ur":"(اور اس لئے آئے ہیں) کہ آپ بنی اسرائیل کو ہمارے ساتھ جانے کی اجازت دیں","hi":"कि तू बनी इसराईल को हमारे साथ भेज दे।"},{"a":18,"ar":"قَالَ أَلَمْ نُرَبِّكَ فِينَا وَلِيدًا وَلَبِثْتَ فِينَا مِنْ عُمُرِكَ سِنِينَ","en":"[Pharaoh] said, \"Did we not raise you among us as a child, and you remained among us for years of your life?","ur":"(فرعون نے موسیٰ سے کہا) کیا ہم نے تم کو کہ ابھی بچّے تھے پرورش نہیں کیا اور تم نے برسوں ہمارے ہاں عمر بسر (نہیں) کی","hi":"(फ़िरऔन ने) कहा : क्या हमने तुझे अपने यहाँ इस हाल में नहीं पाला कि तू बच्चा था और तू हमारे बीच अपनी आयु के कई वर्ष रहा?"},{"a":19,"ar":"وَفَعَلْتَ فَعْلَتَكَ ٱلَّتِى فَعَلْتَ وَأَنتَ مِنَ ٱلْكَـٰفِرِينَ","en":"And [then] you did your deed which you did, and you were of the ungrateful.\"","ur":"اور تم نے وہ کام کیا تھا جو کیا اور تم ناشکرے معلوم ہوتے ہو","hi":"और तूने अपना वह काम किया, जो तूने किया। और तू अकृतज्ञों में से है।"},{"a":20,"ar":"قَالَ فَعَلْتُهَآ إِذًا وَأَنَا۠ مِنَ ٱلضَّآلِّينَ","en":"[Moses] said, \"I did it, then, while I was of those astray [i.e., ignorant].","ur":"(موسیٰ نے) کہاں (ہاں) وہ حرکت مجھ سے ناگہاں سرزد ہوئی تھی اور میں خطا کاروں میں تھا","hi":"(मूसा ने) कहा : मैंने उस समय वह काम इस हाल में किया कि मैं अनजानों में से था।"},{"a":21,"ar":"فَفَرَرْتُ مِنكُمْ لَمَّا خِفْتُكُمْ فَوَهَبَ لِى رَبِّى حُكْمًا وَجَعَلَنِى مِنَ ٱلْمُرْسَلِينَ","en":"So I fled from you when I feared you. Then my Lord granted me judgement [i.e., wisdom and prophet hood] and appointed me [as one] of the messengers.","ur":"تو جب مجھے تم سے ڈر لگا تو تم میں سے بھاگ گیا۔ پھر خدا نے مجھ کو نبوت وعلم بخشا اور مجھے پیغمبروں میں سے کیا","hi":"फिर मैं तुम्हारे पास से भाग गया, जब मैं तुमसे डरा, तो मेरे पालनहार ने मुझे हुक्म (नुबुव्वत एवं ज्ञान) प्रदान किया और मुझे रसूलों में से बना दिया।"},{"a":22,"ar":"وَتِلْكَ نِعْمَةٌ تَمُنُّهَا عَلَىَّ أَنْ عَبَّدتَّ بَنِىٓ إِسْرَٰٓءِيلَ","en":"And is this a favor of which you remind me - that you have enslaved the Children of Israel?\"","ur":"اور (کیا) یہی احسان ہے جو آپ مجھ پر رکھتے ہیں کہ آپ نے بنی اسرائیل کو غلام بنا رکھا ہے","hi":"और यह कोई उपकार है, जो तू मुझपर जता रहा है कि तूने बनी इसराईल काे ग़ुलाम बना रखा है।"},{"a":23,"ar":"قَالَ فِرْعَوْنُ وَمَا رَبُّ ٱلْعَـٰلَمِينَ","en":"Said Pharaoh, \"And what is the Lord of the worlds?\"","ur":"فرعون نے کہا کہ تمام جہان مالک کیا","hi":"फ़िरऔन ने कहा : और 'रब्बुल-आलमीन' (सारे संसारों का पालनहार) क्या है?"},{"a":24,"ar":"قَالَ رَبُّ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ وَمَا بَيْنَهُمَآ ۖ إِن كُنتُم مُّوقِنِينَ","en":"[Moses] said, \"The Lord of the heavens and earth and that between them, if you should be convinced.\"","ur":"کہا کہ آسمانوں اور زمین اور جو کچھ ان دونوں میں ہے سب کا مالک۔ بشرطیکہ تم لوگوں کو یقین ہو","hi":"(मूसा ने) कहा : जो आकाशों और धरती का रब है और जो उनके बीच है उसका भी, यदि तुम विश्वास करने वाले हो।"},{"a":25,"ar":"قَالَ لِمَنْ حَوْلَهُۥٓ أَلَا تَسْتَمِعُونَ","en":"[Pharaoh] said to those around him, \"Do you not hear?\"","ur":"فرعون نے اپنے اہالی موالی سے کہا کہ کیا تم سنتے نہیں","hi":"उसने अपने आस-पास के लोगों से कहा : क्या तुम सुनते नहीं?"},{"a":26,"ar":"قَالَ رَبُّكُمْ وَرَبُّ ءَابَآئِكُمُ ٱلْأَوَّلِينَ","en":"[Moses] said, \"Your Lord and the Lord of your first forefathers.\"","ur":"(موسیٰ نے) کہا کہ تمہارا اور تمہارے پہلے باپ دادا کا مالک","hi":"(मूसा ने) कहा : जो तुम्हारा पालनहार तथा तुम्हारे पहले बाप-दादा का पालनहार है।"},{"a":27,"ar":"قَالَ إِنَّ رَسُولَكُمُ ٱلَّذِىٓ أُرْسِلَ إِلَيْكُمْ لَمَجْنُونٌ","en":"[Pharaoh] said, \"Indeed, your 'messenger' who has been sent to you is mad.\"","ur":"(فرعون نے) کہا کہ (یہ) پیغمبر جو تمہاری طرف بھیجا گیا ہے باؤلا ہے","hi":"(फ़िरऔन ने) कहा : निश्चय तुम्हारा यह रसूल, जो तुम्हारी ओर भेजा गया है, अवश्य पागल है।"},{"a":28,"ar":"قَالَ رَبُّ ٱلْمَشْرِقِ وَٱلْمَغْرِبِ وَمَا بَيْنَهُمَآ ۖ إِن كُنتُمْ تَعْقِلُونَ","en":"[Moses] said, \"Lord of the east and the west and that between them, if you were to reason.\"","ur":"موسیٰ نے کہا کہ مشرق اور مغرب اور جو کچھ ان دونوں میں ہے سب کا مالک، بشرطیکہ تم کو سمجھ ہو","hi":"(मूसा ने) कहा : जो पूर्व तथा पश्चिम रब है और उसका भी जो उन दोनों के बीच है, अगर तुम समझते हो।"},{"a":29,"ar":"قَالَ لَئِنِ ٱتَّخَذْتَ إِلَـٰهًا غَيْرِى لَأَجْعَلَنَّكَ مِنَ ٱلْمَسْجُونِينَ","en":"[Pharaoh] said, \"If you take a god other than me, I will surely place you among those imprisoned.\"","ur":"(فرعون نے) کہا کہ اگر تم نے میرے سوا کسی اور کو معبود بنایا تو میں تمہیں قید کردوں گا","hi":"(फ़िरऔन ने) कहा : निश्चय यदि तूने मेरे अलावा किसी और को पूज्य बनाया, तो मैं तुझे अवश्य ही बंदी बनाए हुए लोगों में शामिल कर दूँगा।‌"},{"a":30,"ar":"قَالَ أَوَلَوْ جِئْتُكَ بِشَىْءٍ مُّبِينٍ","en":"[Moses] said, \"Even if I brought you something [i.e., proof] manifest?\"","ur":"(موسیٰ نے) کہا خواہ میں آپ کے پاس روشن چیز لاؤں (یعنی معجزہ)","hi":"(मूसा ने) कहा : क्या भले ही मैं तेरे पास कोई स्पष्ट चीज़ ले आऊँ?"},{"a":31,"ar":"قَالَ فَأْتِ بِهِۦٓ إِن كُنتَ مِنَ ٱلصَّـٰدِقِينَ","en":"[Pharaoh] said, \"Then bring it, if you should be of the truthful.\"","ur":"فرعون نے کہا اگر سچے ہو تو اسے لاؤ (دکھاؤ)","hi":"उसने कहा : तू उसे ले आ, यदि तू सच्चे लोगों में से है।"},{"a":32,"ar":"فَأَلْقَىٰ عَصَاهُ فَإِذَا هِىَ ثُعْبَانٌ مُّبِينٌ","en":"So [Moses] threw his staff, and suddenly it was a serpent manifest.","ur":"پس انہوں نے اپنی لاٹھی ڈالی تو وہ اسی وقت صریح اژدہا بن گئی","hi":"फिर उसने अपनी लाठी फेंक दी, तो अचानक वह एक प्रत्यक्ष अजगर बन गई।"},{"a":33,"ar":"وَنَزَعَ يَدَهُۥ فَإِذَا هِىَ بَيْضَآءُ لِلنَّـٰظِرِينَ","en":"And he drew out his hand; thereupon it was white for the observers.","ur":"اور اپنا ہاتھ نکالا تو اسی دم دیکھنے والوں کے لئے سفید (براق نظر آنے لگا)","hi":"तथा उसने अपना हाथ निकाला, तो एकाएक वह देखने वालों के लिए सफेद (चमकदार) था।"},{"a":34,"ar":"قَالَ لِلْمَلَإِ حَوْلَهُۥٓ إِنَّ هَـٰذَا لَسَـٰحِرٌ عَلِيمٌ","en":"[Pharaoh] said to the eminent ones around him, \"Indeed, this is a learned magician.","ur":"فرعون نے اپنے گرد کے سرداروں سے کہا کہ یہ تو کامل فن جادوگر ہے","hi":"उसने अपने आस-पास के प्रमुखों से कहा : निश्चय यह तो एक बड़ा कुशल जादूगर है।"},{"a":35,"ar":"يُرِيدُ أَن يُخْرِجَكُم مِّنْ أَرْضِكُم بِسِحْرِهِۦ فَمَاذَا تَأْمُرُونَ","en":"He wants to drive you out of your land by his magic, so what do you advise?\"","ur":"چاہتا ہے کہ تم کو اپنے جادو (کے زور) سے تمہارے ملک سے نکال دے تو تمہاری کیا رائے ہے؟","hi":"जो चाहता है कि अपने जादू के साथ तुम्हें तुम्हारी धरती से निकाल दे। तो तुम क्या आदेश देते हो?"},{"a":36,"ar":"قَالُوٓا۟ أَرْجِهْ وَأَخَاهُ وَٱبْعَثْ فِى ٱلْمَدَآئِنِ حَـٰشِرِينَ","en":"They said, \"Postpone [the matter of] him and his brother and send among the cities gatherers","ur":"انہوں نے کہا کہ اسے اور اس کے بھائی (کے بارے) میں کچھ توقف کیجیئے اور شہروں میں ہرکارے بھیج دیجیئے","hi":"उन्होंने कहा : इसके तथा इसके भाई को मोहलत दें और नगरों में (लोगों को) जमा करने वालों को भेज दें।"},{"a":37,"ar":"يَأْتُوكَ بِكُلِّ سَحَّارٍ عَلِيمٍ","en":"Who will bring you every learned, skilled magician.\"","ur":"کہ سب ماہر جادوگروں کو (جمع کرکے) آپ کے پاس لے آئیں","hi":"कि वे तेरे पास हर बड़ा जादूगर ले आएँ, जो जादू में बहुत कुशल हो।"},{"a":38,"ar":"فَجُمِعَ ٱلسَّحَرَةُ لِمِيقَـٰتِ يَوْمٍ مَّعْلُومٍ","en":"So the magicians were assembled for the appointment of a well-known day.","ur":"تو جادوگر ایک مقررہ دن کی میعاد پر جمع ہوگئے","hi":"तो जादूगर एक निश्चित दिन के नियत समय पर इकट्ठा कर लिए गए।"},{"a":39,"ar":"وَقِيلَ لِلنَّاسِ هَلْ أَنتُم مُّجْتَمِعُونَ","en":"And it was said to the people, \"Will you congregate.","ur":"اور لوگوں سے کہہ دیا گیا کہ تم (سب) کو اکھٹے ہو کر جانا چاہیئے","hi":"तथा लोगों से कहा गया : क्या तुम एकत्र होने वाले हो?"},{"a":40,"ar":"لَعَلَّنَا نَتَّبِعُ ٱلسَّحَرَةَ إِن كَانُوا۟ هُمُ ٱلْغَـٰلِبِينَ","en":"That we might follow the magicians if they are the predominant?\"","ur":"تاکہ اگر جادوگر غالب رہیں تو ہم ان کے پیرو ہوجائیں","hi":"शायद हम इन जादूगरों के अनुयायी बन जाएँ, यदि वही विजयी हों।"},{"a":41,"ar":"فَلَمَّا جَآءَ ٱلسَّحَرَةُ قَالُوا۟ لِفِرْعَوْنَ أَئِنَّ لَنَا لَأَجْرًا إِن كُنَّا نَحْنُ ٱلْغَـٰلِبِينَ","en":"And when the magicians arrived, they said to Pharaoh, \"Is there indeed for us a reward if we are the predominant?\"","ur":"جب جادوگر آگئے تو فرعون سے کہنے لگے اگر ہم غالب رہے تو ہمیں صلہ بھی عطا ہوگا؟","hi":"फिर जब जादूगर आ गए, तो उन्होंने फ़िरऔन से कहा : क्या सचमुच हमें कुछ पुरस्कार मिलेगा, यदि हम ही प्रभावी रहे?"},{"a":42,"ar":"قَالَ نَعَمْ وَإِنَّكُمْ إِذًا لَّمِنَ ٱلْمُقَرَّبِينَ","en":"He said, \"Yes, and indeed, you will then be of those near [to me].\"","ur":"فرعون نے کہا ہاں اور تم مقربوں میں بھی داخل کرلئے جاؤ گے","hi":"उसने कहा : हाँ! और निश्चय तुम उस समय निकटवर्तियों में से हो जाओगे ।"},{"a":43,"ar":"قَالَ لَهُم مُّوسَىٰٓ أَلْقُوا۟ مَآ أَنتُم مُّلْقُونَ","en":"Moses said to them, \"Throw whatever you will throw.\"","ur":"موسیٰ نے ان سے کہا کہ جو چیز ڈالنی چاہتے ہو، ڈالو","hi":"मूसा ने उनसे कहा : फेंको, जो कुछ तुम फेंकने वाले हो।"},{"a":44,"ar":"فَأَلْقَوْا۟ حِبَالَهُمْ وَعِصِيَّهُمْ وَقَالُوا۟ بِعِزَّةِ فِرْعَوْنَ إِنَّا لَنَحْنُ ٱلْغَـٰلِبُونَ","en":"So they threw their ropes and their staffs and said, \"By the might of Pharaoh, indeed it is we who are predominant.\"","ur":"تو انہوں نے اپنی رسیاں اور لاٹھیاں ڈالیں اور کہنے لگے کہ فرعون کے اقبال کی قسم ہم ضرور غالب رہیں گے","hi":"तो उन्होंने अपनी रस्सियाँ और लाठियाँ फेंकीं और कहा : फ़िरऔन के प्रभुत्व की सौगंध! निःसंदेह हम, निश्चय हम ही विजयी रहेंगे।"},{"a":45,"ar":"فَأَلْقَىٰ مُوسَىٰ عَصَاهُ فَإِذَا هِىَ تَلْقَفُ مَا يَأْفِكُونَ","en":"Then Moses threw his staff, and at once it devoured what they falsified.","ur":"پھر موسیٰ نے اپنی لاٹھی ڈالی تو وہ ان چیزوں کو جو جادوگروں نے بنائی تھیں یکایک نگلنے لگی","hi":"फिर मूसा ने अपनी लाठी फेंकी, तो एकाएक वह उन चीज़ों को निगल रही थी, जो वे झूठ बना रहे थे।"},{"a":46,"ar":"فَأُلْقِىَ ٱلسَّحَرَةُ سَـٰجِدِينَ","en":"So the magicians fell down in prostration [to Allāh].","ur":"تب جادوگر سجدے میں گر پڑے","hi":"इसपर जादूगर सजदा करते हुए गिर गए।"},{"a":47,"ar":"قَالُوٓا۟ ءَامَنَّا بِرَبِّ ٱلْعَـٰلَمِينَ","en":"They said, \"We have believed in the Lord of the worlds,","ur":"(اور) کہنے لگے کہ ہم تمام جہان کے مالک پر ایمان لے آئے","hi":"उन्होंने कहा : हम सारे संसारों के पालनहार पर ईमान ले आए।"},{"a":48,"ar":"رَبِّ مُوسَىٰ وَهَـٰرُونَ","en":"The Lord of Moses and Aaron.\"","ur":"جو موسیٰ اور ہارون کا مالک ہے","hi":"मूसा तथा हारून के पालनहार पर।"},{"a":49,"ar":"قَالَ ءَامَنتُمْ لَهُۥ قَبْلَ أَنْ ءَاذَنَ لَكُمْ ۖ إِنَّهُۥ لَكَبِيرُكُمُ ٱلَّذِى عَلَّمَكُمُ ٱلسِّحْرَ فَلَسَوْفَ تَعْلَمُونَ ۚ لَأُقَطِّعَنَّ أَيْدِيَكُمْ وَأَرْجُلَكُم مِّنْ خِلَـٰفٍ وَلَأُصَلِّبَنَّكُمْ أَجْمَعِينَ","en":"[Pharaoh] said, \"You believed him [i.e., Moses] before I gave you permission. Indeed, he is your leader who has taught you magic, but you are going to know. I will surely cut off your hands and your feet on opposite sides, and I will surely crucify you all.\"","ur":"فرعون نے کہا کیا اس سے پہلے کہ میں تم کو اجازت دوں تم اس پر ایمان لے آئے، بےشک یہ تمہارا بڑا ہے جس نے تم کو جادو سکھایا ہے۔ سو عنقریب تم (اس کا انجام) معلوم کرلو گے کہ میں تمہارے ہاتھ اور پاؤں اطراف مخالف سے کٹوا دوں گا اور تم سب کو سولی پر چڑھوا دوں گا","hi":"(फ़िरऔन ने) कहा : तुम उसपर ईमान ले आए, इससे पहले कि मैं तुम्हें अनुमति दूँ? निःसंदेह यह अवश्य तुम्हारा बड़ा (गुरू) है, जिसने तुम्हें जादू सिखाया है। अतः निश्चय तुम जल्दी जान लोगे। मैं अवश्य तुम्हारे हाथ और तुम्हारे पाँव विपरीत दिशा से काट दूँगा तथा निश्चय तुम सभी को अवश्य बुरी तरह सूली पर चढ़ा दूँगा।"},{"a":50,"ar":"قَالُوا۟ لَا ضَيْرَ ۖ إِنَّآ إِلَىٰ رَبِّنَا مُنقَلِبُونَ","en":"They said, \"No harm. Indeed, to our Lord we will return.","ur":"انہوں نے کہا کہ کچھ نقصان (کی بات) نہیں ہم اپنے پروردگار کی طرف لوٹ جانے والے ہیں","hi":"उन्होंने कहा : कोई नुक़सान नहीं, निश्चित रूप से हम अपने पालनहार की ओर पलटने वाले हैं।"},{"a":51,"ar":"إِنَّا نَطْمَعُ أَن يَغْفِرَ لَنَا رَبُّنَا خَطَـٰيَـٰنَآ أَن كُنَّآ أَوَّلَ ٱلْمُؤْمِنِينَ","en":"Indeed, we aspire that our Lord will forgive us our sins because we were the first of the believers.\"","ur":"ہمیں امید ہے کہ ہمارا پروردگار ہمارے گناہ بخش دے گا۔ اس لئے کہ ہم اول ایمان لانے والوں میں ہیں","hi":"हम आशा रखते हैं कि हमारा पालनहार हमारे लिए, हमारे पापों को क्षमा कर देगा, इस कारण कि हम सबसे पहले ईमान लाने वाले हैं।"},{"a":52,"ar":"۞ وَأَوْحَيْنَآ إِلَىٰ مُوسَىٰٓ أَنْ أَسْرِ بِعِبَادِىٓ إِنَّكُم مُّتَّبَعُونَ","en":"And We inspired to Moses, \"Travel by night with My servants; indeed, you will be pursued.\"","ur":"اور ہم نے موسیٰ کی طرف وحی بھیجی کہ ہمارے بندوں کو رات کو لے نکلو کہ (فرعونیوں کی طرف سے) تمہارا تعاقب کیا جائے گا","hi":"और हमने मूसा की ओर वह़्य की कि मेरे बंदों को लेकर रातों-रात निकल जा। निश्चय ही तुम्हारा पीछा किया जाएगा।"},{"a":53,"ar":"فَأَرْسَلَ فِرْعَوْنُ فِى ٱلْمَدَآئِنِ حَـٰشِرِينَ","en":"Then Pharaoh sent among the cities gatherers","ur":"تو فرعون نے شہروں میں نقیب راونہ کئے","hi":"तो फ़िरऔन ने नगरों में (सेना) एकत्र करने वालों को भेज दिया।"},{"a":54,"ar":"إِنَّ هَـٰٓؤُلَآءِ لَشِرْذِمَةٌ قَلِيلُونَ","en":"[And said], \"Indeed, those are but a small band,","ur":"(اور کہا) کہ یہ لوگ تھوڑی سی جماعت ہے","hi":"कि निःसंदेह ये लोग एक छोटा-सा समूह हैं।"},{"a":55,"ar":"وَإِنَّهُمْ لَنَا لَغَآئِظُونَ","en":"And indeed, they are enraging us,","ur":"اور یہ ہمیں غصہ دلا رہے ہیں","hi":"और निःसंदेह ये हमें निश्चित रूप से गुस्सा दिलाने वाले हैं।"},{"a":56,"ar":"وَإِنَّا لَجَمِيعٌ حَـٰذِرُونَ","en":"And indeed, we are a cautious society...\"","ur":"اور ہم سب باسازو سامان ہیں","hi":"और निश्चय ही हम सब चौकन्ना रहने वाले हैं।"},{"a":57,"ar":"فَأَخْرَجْنَـٰهُم مِّن جَنَّـٰتٍ وَعُيُونٍ","en":"So We removed them from gardens and springs","ur":"تو ہم نے ان کو باغوں اور چشموں سے نکال دیا","hi":"इस तरह हमने उन्हें बाग़ों और सोतों से निकाल दिया।"},{"a":58,"ar":"وَكُنُوزٍ وَمَقَامٍ كَرِيمٍ","en":"And treasures and honorable station -","ur":"اور خزانوں اور نفیس مکانات سے","hi":"तथा ख़ज़ानों और उत्तम आवासों से।"},{"a":59,"ar":"كَذَٰلِكَ وَأَوْرَثْنَـٰهَا بَنِىٓ إِسْرَٰٓءِيلَ","en":"Thus. And We caused to inherit it the Children of Israel.","ur":"(ان کے ساتھ ہم نے) اس طرح (کیا) اور ان چیزوں کا وارث بنی اسرائیل کو کر دیا","hi":"ऐसा ही हुआ और हमने उनका वारिस बनी इसराईल को बना दिया।"},{"a":60,"ar":"فَأَتْبَعُوهُم مُّشْرِقِينَ","en":"So they pursued them at sunrise.","ur":"تو انہوں نے سورج نکلتے (یعنی صبح کو) ان کا تعاقب کیا","hi":"तो उन्होंने सूर्योदय के समय उनका पीछा किया।"},{"a":61,"ar":"فَلَمَّا تَرَٰٓءَا ٱلْجَمْعَانِ قَالَ أَصْحَـٰبُ مُوسَىٰٓ إِنَّا لَمُدْرَكُونَ","en":"And when the two companies saw one another, the companions of Moses said, \"Indeed, we are to be overtaken!\"","ur":"جب دونوں جماعتیں آمنے سامنے ہوئیں تو موسیٰ کے ساتھی کہنے لگے کہ ہم تو پکڑ لئے گئے","hi":"फिर जब दोनों गिरोहों ने एक-दूसरे को देखा, तो मूसा के साथियों ने कहा : निःसंदेह हम निश्चय ही पकड़े जाने[12) वाले हैं।"},{"a":62,"ar":"قَالَ كَلَّآ ۖ إِنَّ مَعِىَ رَبِّى سَيَهْدِينِ","en":"[Moses] said, \"No! Indeed, with me is my Lord; He will guide me.\"","ur":"موسیٰ نے کہا ہرگز نہیں میرا پروردگار میرے ساتھ ہے وہ مجھے رستہ بتائے گا","hi":"(मूसा ने) कहा : हरगिज़ नहीं! निश्चय मेरे साथ मेरा पालनहार है। वह अवश्य मेरा मार्गदर्शन करेगा।"},{"a":63,"ar":"فَأَوْحَيْنَآ إِلَىٰ مُوسَىٰٓ أَنِ ٱضْرِب بِّعَصَاكَ ٱلْبَحْرَ ۖ فَٱنفَلَقَ فَكَانَ كُلُّ فِرْقٍ كَٱلطَّوْدِ ٱلْعَظِيمِ","en":"Then We inspired to Moses, \"Strike with your staff the sea,\" and it parted, and each portion was like a great towering mountain.","ur":"اس وقت ہم نے موسیٰ کی طرف وحی بھیجی کہ اپنی لاٹھی دریا پر مارو۔ تو دریا پھٹ گیا۔ اور ہر ایک ٹکڑا (یوں) ہوگیا (کہ) گویا بڑا پہاڑ (ہے)","hi":"तो हमने मूसा की ओर वह़्य की कि अपनी लाठी को सागर पर मारो। (उसने लाठी मारी) तो वह फट गया और हर टुकड़ा बड़े पहाड़ की तरह हो गया।"},{"a":64,"ar":"وَأَزْلَفْنَا ثَمَّ ٱلْـَٔاخَرِينَ","en":"And We advanced thereto the others [i.e., the pursuers].","ur":"اور دوسروں کو وہاں ہم نے قریب کردیا","hi":"तथा वहीं हम दूसरों को निकट ले आए।"},{"a":65,"ar":"وَأَنجَيْنَا مُوسَىٰ وَمَن مَّعَهُۥٓ أَجْمَعِينَ","en":"And We saved Moses and those with him, all together.","ur":"اور موسیٰ اور ان کے ساتھ والوں کو تو بچا لیا","hi":"और हमने मूसा को और जो उसके साथ थे, सबको बचा लिया।"},{"a":66,"ar":"ثُمَّ أَغْرَقْنَا ٱلْـَٔاخَرِينَ","en":"Then We drowned the others.","ur":"پھر دوسروں کو ڈبو دیا","hi":"फिर हमने दूसरों को डुबो दिया।"},{"a":67,"ar":"إِنَّ فِى ذَٰلِكَ لَـَٔايَةً ۖ وَمَا كَانَ أَكْثَرُهُم مُّؤْمِنِينَ","en":"Indeed in that is a sign, but most of them were not to be believers.","ur":"بےشک اس (قصے) میں نشانی ہے۔ لیکن یہ اکثر ایمان لانے والے نہیں","hi":"निःसंदेह इसमें निश्चय एक बड़ी निशानी है। और उनमें से अधिकतर लोग ईमान लाने वाले नहीं थे।"},{"a":68,"ar":"وَإِنَّ رَبَّكَ لَهُوَ ٱلْعَزِيزُ ٱلرَّحِيمُ","en":"And indeed, your Lord - He is the Exalted in Might, the Merciful.","ur":"اور تمہارا پروردگار تو غالب (اور) مہربان ہے","hi":"और निःसंदेह आपका पालनहार, निश्चय वही सबपर प्रभुत्वशाली, अत्यंत दयावान् हैl"},{"a":69,"ar":"وَٱتْلُ عَلَيْهِمْ نَبَأَ إِبْرَٰهِيمَ","en":"And recite to them the news of Abraham,","ur":"اور ان کو ابراہیم کا حال پڑھ کر سنا دو","hi":"तथा आप उन्हें इबराहीम का समाचार सुनाएँ।"},{"a":70,"ar":"إِذْ قَالَ لِأَبِيهِ وَقَوْمِهِۦ مَا تَعْبُدُونَ","en":"When he said to his father and his people, \"What do you worship?\"","ur":"جب انہوں نے اپنے باپ اور اپنی قوم کے لوگوں سے کہا کہ تم کس چیز کو پوجتے ہو","hi":"जब उसने अपने बाप तथा अपनी जाति से कहा : तुम किसकी पूजा करते हो?"},{"a":71,"ar":"قَالُوا۟ نَعْبُدُ أَصْنَامًا فَنَظَلُّ لَهَا عَـٰكِفِينَ","en":"They said, \"We worship idols and remain to them devoted.\"","ur":"وہ کہنے لگے کہ ہم بتوں کو پوجتے ہیں اور ان کی پوجا پر قائم ہیں","hi":"उन्होंने कहा : हम कुछ मूर्तियों की पूजा करते हैं, इसलिए उन्हीं की सेवा में लगे रहते हैं।"},{"a":72,"ar":"قَالَ هَلْ يَسْمَعُونَكُمْ إِذْ تَدْعُونَ","en":"He said, \"Do they hear you when you supplicate?","ur":"ابراہیم نے کہا کہ جب تم ان کو پکارتے ہو تو کیا وہ تمہاری آواز کو سنتے ہیں؟","hi":"उसने कहा : क्या वे तुम्हें सुनते हैं, जब तुम (उन्हें) पुकारते हो?"},{"a":73,"ar":"أَوْ يَنفَعُونَكُمْ أَوْ يَضُرُّونَ","en":"Or do they benefit you, or do they harm?\"","ur":"یا تمہیں کچھ فائدے دے سکتے یا نقصان پہنچا سکتے ہیں؟","hi":"या तुम्हें लाभ देते हैं, या हानि पहुँचाते हैं?"},{"a":74,"ar":"قَالُوا۟ بَلْ وَجَدْنَآ ءَابَآءَنَا كَذَٰلِكَ يَفْعَلُونَ","en":"They said, \"But we found our fathers doing thus.\"","ur":"انہوں نے کہا (نہیں) بلکہ ہم نے اپنے باپ دادا کو اسی طرح کرتے دیکھا ہے","hi":"उन्होंने कहा : बल्कि हमने अपने बाप-दादा को पाया कि वे ऐसा ही करते थे।"},{"a":75,"ar":"قَالَ أَفَرَءَيْتُم مَّا كُنتُمْ تَعْبُدُونَ","en":"He said, \"Then do you see what you have been worshipping,","ur":"ابراہیم نے کہا کیا تم نے دیکھا کہ جن کو تم پوجتے رہے ہو","hi":"उसने कहा : तो क्या तुमने देखा कि जिनको तुम पूजते रहे।"},{"a":76,"ar":"أَنتُمْ وَءَابَآؤُكُمُ ٱلْأَقْدَمُونَ","en":"You and your ancient forefathers?","ur":"تم بھی اور تمہارے اگلے باپ دادا بھی","hi":"तुम तथा तुम्हारे पहले बाप-दादा?"},{"a":77,"ar":"فَإِنَّهُمْ عَدُوٌّ لِّىٓ إِلَّا رَبَّ ٱلْعَـٰلَمِينَ","en":"Indeed, they are enemies to me, except the Lord of the worlds,","ur":"وہ میرے دشمن ہیں۔ مگر خدائے رب العالمین (میرا دوست ہے)","hi":"सो निःसंदेह वे मेरे शत्रु हैं, सिवाय सारे संसारों के पालनहार के।"},{"a":78,"ar":"ٱلَّذِى خَلَقَنِى فَهُوَ يَهْدِينِ","en":"Who created me, and He [it is who] guides me.","ur":"جس نے مجھے پیدا کیا ہے اور وہی مجھے رستہ دکھاتا ہے","hi":"वह जिसने मुझे पैदा किया, फिर वही मेरा मार्गदर्शन करता है।"},{"a":79,"ar":"وَٱلَّذِى هُوَ يُطْعِمُنِى وَيَسْقِينِ","en":"And it is He who feeds me and gives me drink.","ur":"اور وہ جو مجھے کھلاتا اور پلاتا ہے","hi":"और वही जो मुझे खिलाता है और मुझे पिलाता है।"},{"a":80,"ar":"وَإِذَا مَرِضْتُ فَهُوَ يَشْفِينِ","en":"And when I am ill, it is He who cures me","ur":"اور جب میں بیمار پڑتا ہوں تو مجھے شفا بخشتا ہے","hi":"और जब मैं बीमार होता हूँ, तो वही मुझे अच्छा करता है।"},{"a":81,"ar":"وَٱلَّذِى يُمِيتُنِى ثُمَّ يُحْيِينِ","en":"And who will cause me to die and then bring me to life","ur":"اور جو مجھے مارے گا اور پھر زندہ کرے گا","hi":"तथा वह जो मुझे मारेगा, फिर मुझे जीवित करेगा।"},{"a":82,"ar":"وَٱلَّذِىٓ أَطْمَعُ أَن يَغْفِرَ لِى خَطِيٓـَٔتِى يَوْمَ ٱلدِّينِ","en":"And who I aspire that He will forgive me my sin on the Day of Recompense.\"","ur":"اور وہ جس سے میں امید رکھتا ہوں کہ قیامت کے دن میرے گناہ بخشے گا","hi":"तथा वह, जिससे मैं आशा रखता हूँ कि वह बदले के दिन मेरे पाप क्षमा कर देगा।"},{"a":83,"ar":"رَبِّ هَبْ لِى حُكْمًا وَأَلْحِقْنِى بِٱلصَّـٰلِحِينَ","en":"[And he said], \"My Lord, grant me authority and join me with the righteous.","ur":"اے پروردگار مجھے علم ودانش عطا فرما اور نیکوکاروں میں شامل کر","hi":"ऐ मेरे पालनहार! मुझे हुक्म (धर्म का ज्ञान) प्रदान कर और मुझे नेक लोगों के साथ मिला।"},{"a":84,"ar":"وَٱجْعَل لِّى لِسَانَ صِدْقٍ فِى ٱلْـَٔاخِرِينَ","en":"And grant me a mention [i.e., reputation] of honor among later generations.","ur":"اور پچھلے لوگوں میں میرا ذکر نیک (جاری) کر","hi":"और बाद में आने वालों में मुझे सच्ची ख्याति प्रदान कर।"},{"a":85,"ar":"وَٱجْعَلْنِى مِن وَرَثَةِ جَنَّةِ ٱلنَّعِيمِ","en":"And place me among the inheritors of the Garden of Pleasure.","ur":"اور مجھے نعمت کی بہشت کے وارثوں میں کر","hi":"और मुझे नेमतों वाली जन्नत के वारिसों में से बना दे।"},{"a":86,"ar":"وَٱغْفِرْ لِأَبِىٓ إِنَّهُۥ كَانَ مِنَ ٱلضَّآلِّينَ","en":"And forgive my father. Indeed, he has been of those astray.","ur":"اور میرے باپ کو بخش دے کہ وہ گمراہوں میں سے ہے","hi":"तथा मेरे बाप को क्षमा कर दे। निश्चय वह गुमराहों में से था।"},{"a":87,"ar":"وَلَا تُخْزِنِى يَوْمَ يُبْعَثُونَ","en":"And do not disgrace me on the Day they are [all] resurrected -","ur":"اور جس دن لوگ اٹھا کھڑے کئے جائیں گے مجھے رسوا نہ کیجیو","hi":"तथा मुझे रुसवा न कर, जिस दिन लोग उठाए जाएँगे।"},{"a":88,"ar":"يَوْمَ لَا يَنفَعُ مَالٌ وَلَا بَنُونَ","en":"The Day when there will not benefit [anyone] wealth or children","ur":"جس دن نہ مال ہی کچھ فائدہ دے سکا گا اور نہ بیٹے","hi":"जिस दिन न कोई धन लाभ देगा और न बेटे।"},{"a":89,"ar":"إِلَّا مَنْ أَتَى ٱللَّهَ بِقَلْبٍ سَلِيمٍ","en":"But only one who comes to Allāh with a sound heart.\"","ur":"ہاں جو شخص خدا کے پاس پاک دل لے کر آیا (وہ بچ جائے گا)","hi":"परंतु जो अल्लाह के पास पाक-साफ़ दिल लेकर आया।"},{"a":90,"ar":"وَأُزْلِفَتِ ٱلْجَنَّةُ لِلْمُتَّقِينَ","en":"And Paradise will be brought near [that Day] to the righteous.","ur":"اور بہشت پرہیزگاروں کے قریب کردی جائے گی","hi":"और (अपने रब से) डरने वालों के लिए जन्नत निकट लाई जाएगी।"},{"a":91,"ar":"وَبُرِّزَتِ ٱلْجَحِيمُ لِلْغَاوِينَ","en":"And Hellfire will be brought forth for the deviators,","ur":"اور دوزخ گمراہوں کے سامنے لائی جائے گی","hi":"तथा पथभ्रष्ट लोगों के लिए भड़कती आग प्रकट कर दी जाएगी।"},{"a":92,"ar":"وَقِيلَ لَهُمْ أَيْنَ مَا كُنتُمْ تَعْبُدُونَ","en":"And it will be said to them, \"Where are those you used to worship","ur":"اور ان سے کہا جائے گا کہ جن کو تم پوجتے تھے وہ کہاں ہیں؟","hi":"तथा उनसे कहा जाएगा : कहाँ हैं वे, जिन्हें तुम पूजते थे?"},{"a":93,"ar":"مِن دُونِ ٱللَّهِ هَلْ يَنصُرُونَكُمْ أَوْ يَنتَصِرُونَ","en":"Other than Allāh? Can they help you or help themselves?\"","ur":"یعنی جن کو خدا کے سوا (پوجتے تھے) کیا وہ تمہاری مدد کرسکتے ہیں یا خود بدلہ لے سکتے ہیں","hi":"अल्लाह के सिवा। क्या वे तुम्हारी मदद करते हैं, या अपनी रक्षा करते हैं?"},{"a":94,"ar":"فَكُبْكِبُوا۟ فِيهَا هُمْ وَٱلْغَاوُۥنَ","en":"So they will be overturned into it [i.e., Hellfire], they and the deviators","ur":"تو وہ اور گمراہ (یعنی بت اور بت پرست) اوندھے منہ دوزخ میں ڈال دیئے جائیں گے","hi":"फिर वे और सब पथभ्रष्ट लोग उसमें औंधे मुँह फेंक दिए जाएँगे।"},{"a":95,"ar":"وَجُنُودُ إِبْلِيسَ أَجْمَعُونَ","en":"And the soldiers of Iblees, all together.","ur":"اور شیطان کے لشکر سب کے سب (داخل جہنم ہوں گے)","hi":"और इबलीस की समस्त सेनाएँ भी।"},{"a":96,"ar":"قَالُوا۟ وَهُمْ فِيهَا يَخْتَصِمُونَ","en":"They will say while they dispute therein,","ur":"وہ آپس میں جھگڑیں گے اور کہیں گے","hi":"वे उसमें आपस में झगड़ते हुए कहेंगे :"},{"a":97,"ar":"تَٱللَّهِ إِن كُنَّا لَفِى ضَلَـٰلٍ مُّبِينٍ","en":"\"By Allāh, we were indeed in manifest error","ur":"کہ خدا کی قسم ہم تو صریح گمراہی میں تھے","hi":"अल्लाह की क़सम! निःसंदेह हम निश्चय खुली गुमराही में थे।"},{"a":98,"ar":"إِذْ نُسَوِّيكُم بِرَبِّ ٱلْعَـٰلَمِينَ","en":"When we equated you with the Lord of the worlds.","ur":"جب کہ تمہیں (خدائے) رب العالمین کے برابر ٹھہراتے تھے","hi":"जब हम तुम्हें सारे संसारों के पालनहार के बराबर ठहराते थे।"},{"a":99,"ar":"وَمَآ أَضَلَّنَآ إِلَّا ٱلْمُجْرِمُونَ","en":"And no one misguided us except the criminals.","ur":"اور ہم کو ان گنہگاروں ہی نے گمراہ کیا تھا","hi":"और हमें तो सिर्फ़ इन अपराधियों ने गुमराह किया।"},{"a":100,"ar":"فَمَا لَنَا مِن شَـٰفِعِينَ","en":"So now we have no intercessors","ur":"تو (آج) نہ کوئی ہمارا سفارش کرنے والا ہے","hi":"अब न हमारे लिए कोई सिफारिश करने वाले हैं।"},{"a":101,"ar":"وَلَا صَدِيقٍ حَمِيمٍ","en":"And not a devoted friend.","ur":"اور نہ گرم جوش دوست","hi":"और न कोई घनिष्ट मित्र।"},{"a":102,"ar":"فَلَوْ أَنَّ لَنَا كَرَّةً فَنَكُونَ مِنَ ٱلْمُؤْمِنِينَ","en":"Then if we only had a return [to the world] and could be of the believers...\"","ur":"کاش ہمیں (دنیا میں) پھر جانا ہو تم ہم مومنوں میں ہوجائیں","hi":"तो यदि वास्तव में हमारे लिए वापस जाने का अवसर होता, तो हम ईमानवालों में से हो जाते।"},{"a":103,"ar":"إِنَّ فِى ذَٰلِكَ لَـَٔايَةً ۖ وَمَا كَانَ أَكْثَرُهُم مُّؤْمِنِينَ","en":"Indeed in that is a sign, but most of them were not to be believers.","ur":"بےشک اس میں نشانی ہے اور ان میں اکثر ایمان لانے والے نہیں","hi":"निःसंदेह इसमें निश्चय एक बड़ी निशानी है। और उनमें से अधिकतर ईमानवाले नहीं थे।"},{"a":104,"ar":"وَإِنَّ رَبَّكَ لَهُوَ ٱلْعَزِيزُ ٱلرَّحِيمُ","en":"And indeed, your Lord - He is the Exalted in Might, the Merciful.","ur":"اور تمہارا پروردگار تو غالب اور مہربان ہے","hi":"और निःसंदेह आपका पालनहार, निश्चय वही सबपर प्रभुत्वशाली, अत्यंत दयावान् हैl"},{"a":105,"ar":"كَذَّبَتْ قَوْمُ نُوحٍ ٱلْمُرْسَلِينَ","en":"The people of Noah denied the messengers","ur":"قوم نوح نے بھی پیغمبروں کو جھٹلایا","hi":"नूह़ की जाति ने रसूलों को झुठलाया।"},{"a":106,"ar":"إِذْ قَالَ لَهُمْ أَخُوهُمْ نُوحٌ أَلَا تَتَّقُونَ","en":"When their brother Noah said to them, \"Will you not fear Allāh?","ur":"جب ان سے ان کے بھائی نوح نے کہا کہ تم ڈرتے کیوں نہیں","hi":"जब उनसे उनके भाई नूह़ ने कहा : क्या तुम डरते नहीं?"},{"a":107,"ar":"إِنِّى لَكُمْ رَسُولٌ أَمِينٌ","en":"Indeed, I am to you a trustworthy messenger.","ur":"میں تو تمہارا امانت دار ہوں","hi":"निःसंदेह मैं तुम्हारे लिए एक अमानतदार रसूल हूँ।"},{"a":108,"ar":"فَٱتَّقُوا۟ ٱللَّهَ وَأَطِيعُونِ","en":"So fear Allāh and obey me.","ur":"تو خدا سے ڈرو اور میرا کہا مانو","hi":"अतः तुम अल्लाह से डरो और मेरी बात मानो।"},{"a":109,"ar":"وَمَآ أَسْـَٔلُكُمْ عَلَيْهِ مِنْ أَجْرٍ ۖ إِنْ أَجْرِىَ إِلَّا عَلَىٰ رَبِّ ٱلْعَـٰلَمِينَ","en":"And I do not ask you for it any payment. My payment is only from the Lord of the worlds.","ur":"اور اس کام کا تم سے کچھ صلہ نہیں مانگتا۔ میرا صلہ تو خدائے رب العالمین ہی پر ہے","hi":"मैं इस (कार्य) पर तुमसे कोई पारिश्रमिक (बदला) नहीं माँगता। मेरा बदला तो केवल सारे संसारों के पालनहार पर है।"},{"a":110,"ar":"فَٱتَّقُوا۟ ٱللَّهَ وَأَطِيعُونِ","en":"So fear Allāh and obey me.\"","ur":"تو خدا سے ڈرو اور میرے کہنے پر چلو","hi":"अतः तुम अल्लाह से डरो और मेरी बात मानो।"},{"a":111,"ar":"۞ قَالُوٓا۟ أَنُؤْمِنُ لَكَ وَٱتَّبَعَكَ ٱلْأَرْذَلُونَ","en":"They said, \"Should we believe you while you are followed by the lowest [class of people]?\"","ur":"وہ بولے کہ کیا ہم تم کو مان لیں اور تمہارے پیرو تو رذیل لوگ ہوتے ہیں","hi":"उन्होंने कहा : क्या हम तुझपर ईमान ले आएँ, जबकि तेरे पीछे चलने वाले अत्यंत नीच लोग हैं?"},{"a":112,"ar":"قَالَ وَمَا عِلْمِى بِمَا كَانُوا۟ يَعْمَلُونَ","en":"He said, \"And what is my knowledge of what they used to do?","ur":"نوح نے کہا کہ مجھے کیا معلوم کہ وہ کیا کرتے ہیں","hi":"(नूह़ ने) कहा : मूझे क्या मालूम कि वे क्या कर्म करते रहे हैं?"},{"a":113,"ar":"إِنْ حِسَابُهُمْ إِلَّا عَلَىٰ رَبِّى ۖ لَوْ تَشْعُرُونَ","en":"Their account is only upon my Lord, if you [could] perceive.","ur":"ان کا حساب (اعمال) میرے پروردگار کے ذمے ہے کاش تم سمجھو","hi":"उनका ह़िसाब तो मेरे पालनहार ही के ज़िम्मे है, यदि तुम समझो।"},{"a":114,"ar":"وَمَآ أَنَا۠ بِطَارِدِ ٱلْمُؤْمِنِينَ","en":"And I am not one to drive away the believers.","ur":"اور میں مومنوں کو نکال دینے والا نہیں ہوں","hi":"और मैं ईमान वालों को धुतकारने वाला नहीं हूँ।"},{"a":115,"ar":"إِنْ أَنَا۠ إِلَّا نَذِيرٌ مُّبِينٌ","en":"I am only a clear warner.\"","ur":"میں تو صرف کھول کھول کر نصیحت کرنے والا ہوں","hi":"मैं तो बस एक खुला डराने वाला हूँ"},{"a":116,"ar":"قَالُوا۟ لَئِن لَّمْ تَنتَهِ يَـٰنُوحُ لَتَكُونَنَّ مِنَ ٱلْمَرْجُومِينَ","en":"They said, \"If you do not desist, O Noah, you will surely be of those who are stoned.\"","ur":"انہوں نے کہا کہ نوح اگر تم باز نہ آؤ گے تو سنگسار کردیئے جاؤ گے","hi":"उन्होंने कहा : ऐ नूह़! यदि तू बाज़ नहीं आया, तो अवश्य संगसार किए गए लोगों में से हो जाएगा।"},{"a":117,"ar":"قَالَ رَبِّ إِنَّ قَوْمِى كَذَّبُونِ","en":"He said, \"My Lord, indeed my people have denied me.","ur":"نوح نے کہا کہ پروردگار میری قوم نے تو مجھے جھٹلا دیا","hi":"उसने कहा : ऐ मेरे पालनहार! निःसंदेह मेरी जाति ने मुझे झुठला दिया!"},{"a":118,"ar":"فَٱفْتَحْ بَيْنِى وَبَيْنَهُمْ فَتْحًا وَنَجِّنِى وَمَن مَّعِىَ مِنَ ٱلْمُؤْمِنِينَ","en":"Then judge between me and them with decisive judgement and save me and those with me of the believers.\"","ur":"سو تو میرے اور ان کے درمیان ایک کھلا فیصلہ کردے اور مجھے اور جو میرے ساتھ ہیں ان کو بچا لے","hi":"अतः तू मेरे और उनके बीच दो-टूक निर्णय कर दे, तथा मुझे और जो ईमानवाले मेरे साथ हैं, उन्हें बचा ले।"},{"a":119,"ar":"فَأَنجَيْنَـٰهُ وَمَن مَّعَهُۥ فِى ٱلْفُلْكِ ٱلْمَشْحُونِ","en":"So We saved him and those with him in the laden ship.","ur":"پس ہم نے ان کو اور جو ان کے ساتھ کشتی میں سوار تھے، ان کو بچا لیا","hi":"तो हमने उसे और उन लोगों को जो उसके साथ भरी हुई नाव में थे, बचा लिया।"},{"a":120,"ar":"ثُمَّ أَغْرَقْنَا بَعْدُ ٱلْبَاقِينَ","en":"Then We drowned thereafter the remaining ones.","ur":"پھر اس کے بعد باقی لوگوں کو ڈبو دیا","hi":"फिर उसके बाद शेष लोगों को डुबो दिया।"},{"a":121,"ar":"إِنَّ فِى ذَٰلِكَ لَـَٔايَةً ۖ وَمَا كَانَ أَكْثَرُهُم مُّؤْمِنِينَ","en":"Indeed in that is a sign, but most of them were not to be believers.","ur":"بےشک اس میں نشانی ہے اور ان میں اکثر ایمان لانے والے نہیں تھے","hi":"निःसंदेह इसमें निश्चय एक बड़ी निशानी है। और उनमें से अधिकतर ईमानवाले नहीं थे।"},{"a":122,"ar":"وَإِنَّ رَبَّكَ لَهُوَ ٱلْعَزِيزُ ٱلرَّحِيمُ","en":"And indeed, your Lord - He is the Exalted in Might, the Merciful.","ur":"اور تمہارا پروردگار تو غالب (اور) مہربان ہے","hi":"और निःसंदेह आपका पालनहार, निश्चय वही सबपर प्रभुत्वशाली, अत्यंत दयावान् है।"},{"a":123,"ar":"كَذَّبَتْ عَادٌ ٱلْمُرْسَلِينَ","en":"ʿAad denied the messengers","ur":"عاد نے بھی پیغمبروں کو جھٹلایا","hi":"आद ने रसूलों को झुठलाया।"},{"a":124,"ar":"إِذْ قَالَ لَهُمْ أَخُوهُمْ هُودٌ أَلَا تَتَّقُونَ","en":"When their brother Hūd said to them, \"Will you not fear Allāh?","ur":"جب ان سے ان کے بھائی ہود نے کہا کیا تم ڈرتے نہیں","hi":"जब उनसे उनके भाई हूद ने कहा : क्या तुम डरते नहीं हो?"},{"a":125,"ar":"إِنِّى لَكُمْ رَسُولٌ أَمِينٌ","en":"Indeed, I am to you a trustworthy messenger.","ur":"میں تو تمہارا امانت دار پیغمبر ہوں","hi":"निःसंदेह मैं तुम्हारे लिए एक अमानतदार रसूल हूँ।"},{"a":126,"ar":"فَٱتَّقُوا۟ ٱللَّهَ وَأَطِيعُونِ","en":"So fear Allāh and obey me.","ur":"تو خدا سے ڈرو اور میرا کہا مانو","hi":"अतः तुम अल्लाह से डरो और मेरी बात मानो।"},{"a":127,"ar":"وَمَآ أَسْـَٔلُكُمْ عَلَيْهِ مِنْ أَجْرٍ ۖ إِنْ أَجْرِىَ إِلَّا عَلَىٰ رَبِّ ٱلْعَـٰلَمِينَ","en":"And I do not ask you for it any payment. My payment is only from the Lord of the worlds.","ur":"اور میں اس کا تم سے کچھ بدلہ نہیں مانگتا۔ میرا بدلہ (خدائے) رب العالمین کے ذمے ہے","hi":"मैं इस (कार्य) पर तुमसे कोई पारिश्रमिक (बदला) नहीं माँगता, मेरा बदला तो केवल सारे संसारों के पालनहार पर है।"},{"a":128,"ar":"أَتَبْنُونَ بِكُلِّ رِيعٍ ءَايَةً تَعْبَثُونَ","en":"Do you construct on every elevation a sign, amusing yourselves,","ur":"بھلا تم ہر اونچی جگہ پر نشان تعمیر کرتے ہو","hi":"क्या तुम हर ऊँचे स्थान पर एक स्मारक बनाते हो? इस स्थिति में कि व्यर्थ कार्य करते हो।"},{"a":129,"ar":"وَتَتَّخِذُونَ مَصَانِعَ لَعَلَّكُمْ تَخْلُدُونَ","en":"And take for yourselves constructions [i.e., palaces and fortresses] that you might abide eternally?","ur":"اور محل بناتے ہو شاید تم ہمیشہ رہو گے","hi":"तथा बड़े-बड़े भवन बनाते हो, शायद कि तुम सदा जीवित रहोगे।"},{"a":130,"ar":"وَإِذَا بَطَشْتُم بَطَشْتُمْ جَبَّارِينَ","en":"And when you strike, you strike as tyrants.","ur":"اور جب (کسی کو) پکڑتے ہو تو ظالمانہ پکڑتے ہو","hi":"और जब तुम पकड़ते हो, तो बड़ी निर्दयता से पकड़ते हो।"},{"a":131,"ar":"فَٱتَّقُوا۟ ٱللَّهَ وَأَطِيعُونِ","en":"So fear Allāh and obey me.","ur":"تو خدا سے ڈرو اور میری اطاعت کرو","hi":"अतः अल्लाह से डरो और जो मैं कहता हूँ, उसे मानो।"},{"a":132,"ar":"وَٱتَّقُوا۟ ٱلَّذِىٓ أَمَدَّكُم بِمَا تَعْلَمُونَ","en":"And fear He who provided you with that which you know,","ur":"اور اس سے جس نے تم کو ان چیزوں سے مدد دی جن کو تم جانتے ہو۔ ڈرو","hi":"तथा उससे डरो जिसने उन चीज़ों से तुम्हारी मदद की, जिन्हें तुम जानते हो।"},{"a":133,"ar":"أَمَدَّكُم بِأَنْعَـٰمٍ وَبَنِينَ","en":"Provided you with grazing livestock and children","ur":"اس نے تمہیں چارپایوں اور بیٹوں سے مدد دی","hi":"उसने चौपायों और बेटों से तुम्हारी मदद की।"},{"a":134,"ar":"وَجَنَّـٰتٍ وَعُيُونٍ","en":"And gardens and springs.","ur":"اور باغوں اور چشموں سے","hi":"तथा बाग़ों और जल स्रोताें से।"},{"a":135,"ar":"إِنِّىٓ أَخَافُ عَلَيْكُمْ عَذَابَ يَوْمٍ عَظِيمٍ","en":"Indeed, I fear for you the punishment of a terrible day.\"","ur":"مجھ کو تمہارے بارے میں بڑے (سخت) دن کے عذاب کا خوف ہے","hi":"निश्चय ही मैं तुमपर एक बड़े दिन की यातना से डरता हूँ।"},{"a":136,"ar":"قَالُوا۟ سَوَآءٌ عَلَيْنَآ أَوَعَظْتَ أَمْ لَمْ تَكُن مِّنَ ٱلْوَٰعِظِينَ","en":"They said, \"It is all the same to us whether you advise or are not of the advisors.","ur":"وہ کہنے لگے کہ ہمیں خواہ نصیحت کرو یا نہ کرو ہمارے لئے یکساں ہے","hi":"उन्होंने कहा : हमारे लिए बराबर है कि तू नसीहत करे, या नसीहत करने वालों में से हो।"},{"a":137,"ar":"إِنْ هَـٰذَآ إِلَّا خُلُقُ ٱلْأَوَّلِينَ","en":"This is not but the custom of the former peoples,","ur":"یہ تو اگلوں ہی کے طریق ہیں","hi":"यह तो केवल पहले लोगों की आदत है।"},{"a":138,"ar":"وَمَا نَحْنُ بِمُعَذَّبِينَ","en":"And we are not to be punished.\"","ur":"اور ہم پر کوئی عذاب نہیں آئے گا","hi":"और हम निश्चित रूप से दंडित नहीं होंगे।"},{"a":139,"ar":"فَكَذَّبُوهُ فَأَهْلَكْنَـٰهُمْ ۗ إِنَّ فِى ذَٰلِكَ لَـَٔايَةً ۖ وَمَا كَانَ أَكْثَرُهُم مُّؤْمِنِينَ","en":"And they denied him, so We destroyed them. Indeed in that is a sign, but most of them were not to be believers.","ur":"تو انہوں نے ہود کو جھٹلایا تو ہم نے ان کو ہلاک کر ڈالا۔ بےشک اس میں نشانی ہے۔ اور ان میں اکثر ایمان لانے والے نہیں تھے","hi":"तो उन्होंने उसे झुठला दिया, तो हमने उन्हें विनष्ट कर दिया। निःसंदेह इसमें निश्चय एक बड़ी निशानी है। और उनमें से अधिकतर लोग ईमानवाले नहीं थे।"},{"a":140,"ar":"وَإِنَّ رَبَّكَ لَهُوَ ٱلْعَزِيزُ ٱلرَّحِيمُ","en":"And indeed, your Lord - He is the Exalted in Might, the Merciful.","ur":"اور تمہارا پروردگار تو غالب اور مہربان ہے","hi":"तथा निःसंदेह आपका पालनहार, निश्चय वही सबपर प्रभुत्वशाली, अत्यंत दयावान् है।"},{"a":141,"ar":"كَذَّبَتْ ثَمُودُ ٱلْمُرْسَلِينَ","en":"Thamūd denied the messengers","ur":"(اور) قوم ثمود نے بھی پیغمبروں کو جھٹلا دیا","hi":"समूद ने रसूलों को झुठलाया।"},{"a":142,"ar":"إِذْ قَالَ لَهُمْ أَخُوهُمْ صَـٰلِحٌ أَلَا تَتَّقُونَ","en":"When their brother Ṣāliḥ said to them, \"Will you not fear Allāh?","ur":"جب ان سے ان کے بھائی صالح نے کہا کہ تم ڈرتے کیوں نہیں؟","hi":"जब उनसे उनके भाई सालेह़ ने कहा : क्या तुम डरते नहीं हो?"},{"a":143,"ar":"إِنِّى لَكُمْ رَسُولٌ أَمِينٌ","en":"Indeed, I am to you a trustworthy messenger.","ur":"میں تو تمہارا امانت دار ہوں","hi":"निःसंदेह मैं तुम्हारे लिए एक अमानतदार रसूल हूँ।"},{"a":144,"ar":"فَٱتَّقُوا۟ ٱللَّهَ وَأَطِيعُونِ","en":"So fear Allāh and obey me.","ur":"تو خدا سے ڈرو اور میرا کہا مانو","hi":"अतः अल्लाह से डरो और जो मैं कहता हूँ, उसका पालन करो।"},{"a":145,"ar":"وَمَآ أَسْـَٔلُكُمْ عَلَيْهِ مِنْ أَجْرٍ ۖ إِنْ أَجْرِىَ إِلَّا عَلَىٰ رَبِّ ٱلْعَـٰلَمِينَ","en":"And I do not ask you for it any payment. My payment is only from the Lord of the worlds.","ur":"اور میں اس کا تم سے بدلہ نہیں مانگتا۔ میرا بدلہ (خدا) رب العالمین کے ذمے ہے","hi":"मैं इसपर तुमसे कोई पारिश्रमिक (बदला) नहीं माँगता। मेरा बदला तो केवल सारे संसारों के पालनहार पर है।"},{"a":146,"ar":"أَتُتْرَكُونَ فِى مَا هَـٰهُنَآ ءَامِنِينَ","en":"Will you be left in what is here, secure [from death],","ur":"کیا وہ چیزیں (تمہیں یہاں میسر) ہیں ان میں تم بےخوف چھوڑ دیئے جاؤ گے","hi":"क्या तुम उन चीज़ों में जो यहाँ हैं, निश्चिंत छोड़ दिए जाओगे?"},{"a":147,"ar":"فِى جَنَّـٰتٍ وَعُيُونٍ","en":"Within gardens and springs","ur":"(یعنی) باغ اور چشمے","hi":"बाग़ों तथा स्रोतों में।"},{"a":148,"ar":"وَزُرُوعٍ وَنَخْلٍ طَلْعُهَا هَضِيمٌ","en":"And fields of crops and palm trees with softened fruit?","ur":"اور کھیتیاں اور کھجوریں جن کے خوشے لطیف ونازک ہوتے ہیں","hi":"तथा खेतों और खजूर के पेड़ों में, जिनके फल मुलायम और पके हुए हैं।"},{"a":149,"ar":"وَتَنْحِتُونَ مِنَ ٱلْجِبَالِ بُيُوتًا فَـٰرِهِينَ","en":"And you carve out of the mountains, homes, with skill.","ur":"اور تکلف سے پہاڑوں میں تراش خراش کر گھر بناتے ہو","hi":"तथा तुम पर्वतों को काटकर बड़ी निपुणता के साथ घर बनाते हो।"},{"a":150,"ar":"فَٱتَّقُوا۟ ٱللَّهَ وَأَطِيعُونِ","en":"So fear Allāh and obey me.","ur":"تو خدا سے ڈرو اور میرے کہنے پر چلو","hi":"अतः अल्लाह से डरो और मेरा आज्ञापालन करो।"},{"a":151,"ar":"وَلَا تُطِيعُوٓا۟ أَمْرَ ٱلْمُسْرِفِينَ","en":"And do not obey the order of the transgressors,","ur":"اور حد سے تجاوز کرنے والوں کی بات نہ مانو","hi":"और हद से आगे बढ़ने वालों का हुक्म न मानो।"},{"a":152,"ar":"ٱلَّذِينَ يُفْسِدُونَ فِى ٱلْأَرْضِ وَلَا يُصْلِحُونَ","en":"Who cause corruption in the land and do not amend.\"","ur":"جو ملک میں فساد کرتے ہیں اور اصلاح نہیں کرتے","hi":"जो धरती में बिगाड़ पैदा करते हैं और सुधार नहीं करते।"},{"a":153,"ar":"قَالُوٓا۟ إِنَّمَآ أَنتَ مِنَ ٱلْمُسَحَّرِينَ","en":"They said, \"You are only of those affected by magic.","ur":"وہ کہنے لگے کہ تم تو جادو زدہ ہو","hi":"उन्होंने कहा : निःसंदेह तू उन लोगों में से है जिनपर प्रबल जादू किया गया है।"},{"a":154,"ar":"مَآ أَنتَ إِلَّا بَشَرٌ مِّثْلُنَا فَأْتِ بِـَٔايَةٍ إِن كُنتَ مِنَ ٱلصَّـٰدِقِينَ","en":"You are but a man like ourselves, so bring a sign, if you should be of the truthful.\"","ur":"تم اور کچھ نہیں ہماری طرح آدمی ہو۔ اگر سچے ہو تو کوئی نشانی پیش کرو","hi":"तू तो बस हमारे ही जैसा एक मनुष्य है। अतः कोई निशानी ले आ, यदि तू सच्चों में से है।"},{"a":155,"ar":"قَالَ هَـٰذِهِۦ نَاقَةٌ لَّهَا شِرْبٌ وَلَكُمْ شِرْبُ يَوْمٍ مَّعْلُومٍ","en":"He said, \"This is a she-camel. For her is a [time of] drink, and for you is a [time of] drink, [each] on a known day.","ur":"صالح نے کہا (دیکھو) یہ اونٹنی ہے (ایک دن) اس کی پانی پینے کی باری ہے اور ایک معین روز تمہاری باری","hi":"उसने कहा : यह एक ऊँटनी है। इसके लिए पानी पीने की एक बारी है और तुम्हारे लिए एक निश्चित दिन पानी पीने की बारी है।"},{"a":156,"ar":"وَلَا تَمَسُّوهَا بِسُوٓءٍ فَيَأْخُذَكُمْ عَذَابُ يَوْمٍ عَظِيمٍ","en":"And do not touch her with harm, lest you be seized by the punishment of a terrible day.\"","ur":"اور اس کو کوئی تکلیف نہ دینا (نہیں تو) تم کو سخت عذاب آ پکڑے گا","hi":"तथा उसे किसी बुराई से हाथ न लगाना, अन्यथा तुम्हें एक बड़े दिन की यातना पकड़ लेगी।"},{"a":157,"ar":"فَعَقَرُوهَا فَأَصْبَحُوا۟ نَـٰدِمِينَ","en":"But they hamstrung her and so became regretful.","ur":"تو انہوں نے اس کی کونچیں کاٹ ڈالیں پھر نادم ہوئے","hi":"तो उन्होंने उसकी कूँचें काट दीं, फिर पछताने वाले हो गए।"},{"a":158,"ar":"فَأَخَذَهُمُ ٱلْعَذَابُ ۗ إِنَّ فِى ذَٰلِكَ لَـَٔايَةً ۖ وَمَا كَانَ أَكْثَرُهُم مُّؤْمِنِينَ","en":"And the punishment seized them. Indeed in that is a sign, but most of them were not to be believers.","ur":"سو ان کو عذاب نے آن پکڑا۔ بےشک اس میں نشانی ہے۔ اور ان میں اکثر ایمان لانے والے نہیں تھے","hi":"तो उन्हें यातना ने पकड़ लिया। निःसंदेह इसमें निश्चय एक बड़ी निशानी है। और उनमें से अधिकतर ईमानवाले नहीं थे।"},{"a":159,"ar":"وَإِنَّ رَبَّكَ لَهُوَ ٱلْعَزِيزُ ٱلرَّحِيمُ","en":"And indeed, your Lord - He is the Exalted in Might, the Merciful.","ur":"اور تمہارا پروردگار تو غالب (اور) مہربان ہے","hi":"और निःसंदेह आपका पालनहार, निश्चय वही सबपर प्रभुत्वशाली, अत्यंत दयावान् है।"},{"a":160,"ar":"كَذَّبَتْ قَوْمُ لُوطٍ ٱلْمُرْسَلِينَ","en":"The people of Lot denied the messengers","ur":"(اور قوم) لوط نے بھی پیغمبروں کو جھٹلایا","hi":"लूत की जाति ने रसूलों को झुठलाया।"},{"a":161,"ar":"إِذْ قَالَ لَهُمْ أَخُوهُمْ لُوطٌ أَلَا تَتَّقُونَ","en":"When their brother Lot said to them, \"Will you not fear Allāh?","ur":"جب ان سے ان کے بھائی لوط نے کہا کہ تم کیوں نہیں ڈرتے؟","hi":"जब उनके भाई लूत ने उनसे कहा : क्या तुम डरते नहीं हो?"},{"a":162,"ar":"إِنِّى لَكُمْ رَسُولٌ أَمِينٌ","en":"Indeed, I am to you a trustworthy messenger.","ur":"میں تو تمہارا امانت دار پیغمبر ہوں","hi":"निःसंदेह मैं तुम्हारे लिए एक अमानतदार रसूल हूँ।"},{"a":163,"ar":"فَٱتَّقُوا۟ ٱللَّهَ وَأَطِيعُونِ","en":"So fear Allāh and obey me.","ur":"تو خدا سے ڈرو اور میرا کہا مانو","hi":"अतः तुम अल्लाह से डरो और मेरी बात मानो।"},{"a":164,"ar":"وَمَآ أَسْـَٔلُكُمْ عَلَيْهِ مِنْ أَجْرٍ ۖ إِنْ أَجْرِىَ إِلَّا عَلَىٰ رَبِّ ٱلْعَـٰلَمِينَ","en":"And I do not ask you for it any payment. My payment is only from the Lord of the worlds.","ur":"اور میں تم سے اس (کام) کا بدلہ نہیں مانگتا۔ میرا بدلہ (خدائے) رب العالمین کے ذمے ہے","hi":"मैं इस (कार्य) पर तुमसे कोई पारिश्रमिक (बदला) नहीं माँगता, मेरा बदला तो केवल सारे संसारों के पालनहार पर है।"},{"a":165,"ar":"أَتَأْتُونَ ٱلذُّكْرَانَ مِنَ ٱلْعَـٰلَمِينَ","en":"Do you approach males among the worlds","ur":"کیا تم اہل عالم میں سے لڑکوں پر مائل ہوتے ہو","hi":"क्या सभी संसारों में से तुम पुरुषों के पास आते हो।"},{"a":166,"ar":"وَتَذَرُونَ مَا خَلَقَ لَكُمْ رَبُّكُم مِّنْ أَزْوَٰجِكُم ۚ بَلْ أَنتُمْ قَوْمٌ عَادُونَ","en":"And leave what your Lord has created for you as mates? But you are a people transgressing.\"","ur":"اور تمہارے پروردگار نے جو تمہارے لئے تمہاری بیویاں پیدا کی ہیں ان کو چھوڑ دیتے ہو۔ حقیقت یہ ہے کہ تم حد سے نکل جانے والے ہو","hi":"तथा उन्हें छोड़ देते हो, जो तुम्हारे पालनहार ने तुम्हारे लिए तुम्हारी पत्नियाँ पैदा की हैं। बल्कि तुम हद से आगे बढ़ने वाले लोग हो।"},{"a":167,"ar":"قَالُوا۟ لَئِن لَّمْ تَنتَهِ يَـٰلُوطُ لَتَكُونَنَّ مِنَ ٱلْمُخْرَجِينَ","en":"They said, \"If you do not desist, O Lot, you will surely be of those evicted.\"","ur":"وہ کہنے لگے کہ لوط اگر تم باز نہ آؤ گے تو شہر بدر کردیئے جاؤ گے","hi":"उन्होंने कहा : ऐ लूत! निःसंदेह यदि तू नहीं रुका, तो निश्चित रूप से तू अवश्य निष्कासित लोगों में से हो जाएगा।"},{"a":168,"ar":"قَالَ إِنِّى لِعَمَلِكُم مِّنَ ٱلْقَالِينَ","en":"He said, \"Indeed, I am, toward your deed, of those who detest [it].","ur":"لوط نے کہا کہ میں تمہارے کام کا سخت دشمن ہوں","hi":"उसने कहा : निःसंदेह मैं तुम्हारे काम से सख़्त घृणा करने वालों में से हूँ।"},{"a":169,"ar":"رَبِّ نَجِّنِى وَأَهْلِى مِمَّا يَعْمَلُونَ","en":"My Lord, save me and my family from [the consequence of] what they do.\"","ur":"اے میرے پروردگار مجھ کو اور میرے گھر والوں کو ان کے کاموں (کے وبال) سے نجات دے","hi":"ऐ मेरे पालनहार! मुझे तथा मेरे घर वालों को उससे बचा ले, जो ये करते हैं।"},{"a":170,"ar":"فَنَجَّيْنَـٰهُ وَأَهْلَهُۥٓ أَجْمَعِينَ","en":"So We saved him and his family, all,","ur":"سو ہم نے ان کو اور ان کے گھر والوں کو سب کو نجات دی","hi":"तो हमने उसे और उसके सभी घर वालों को बचा लिया।"},{"a":171,"ar":"إِلَّا عَجُوزًا فِى ٱلْغَـٰبِرِينَ","en":"Except an old woman among those who remained behind.","ur":"مگر ایک بڑھیا کہ پیچھے رہ گئی","hi":"सिवाय एक बुढ़िया के, जो पीछे रहने वालों में से थी।"},{"a":172,"ar":"ثُمَّ دَمَّرْنَا ٱلْـَٔاخَرِينَ","en":"Then We destroyed the others.","ur":"پھر ہم نے اوروں کو ہلاک کردیا","hi":"फिर हमने दूसरों को विनष्ट कर दिया।"},{"a":173,"ar":"وَأَمْطَرْنَا عَلَيْهِم مَّطَرًا ۖ فَسَآءَ مَطَرُ ٱلْمُنذَرِينَ","en":"And We rained upon them a rain [of stones], and evil was the rain of those who were warned.","ur":"اور ان پر مینھہ برسایا۔ سو جو مینھہ ان (لوگوں) پر (برسا) جو ڈرائے گئے برا تھا","hi":"और हमने उनपर ज़ोरदार बारिश बरसाई। तो उन लोगों की बारिश बहुत बुरी थी, जिन्हें डराया गया था।"},{"a":174,"ar":"إِنَّ فِى ذَٰلِكَ لَـَٔايَةً ۖ وَمَا كَانَ أَكْثَرُهُم مُّؤْمِنِينَ","en":"Indeed in that is a sign, but most of them were not to be believers.","ur":"بےشک اس میں نشانی ہے۔ اور ان میں اکثر ایمان لانے والے نہیں تھے","hi":"निःसंदेह इसमें निश्चय एक बड़ी निशानी है। और उनमें से अधिकतर ईमानवाले नहीं थे।"},{"a":175,"ar":"وَإِنَّ رَبَّكَ لَهُوَ ٱلْعَزِيزُ ٱلرَّحِيمُ","en":"And indeed, your Lord - He is the Exalted in Might, the Merciful.","ur":"اور تمہارا پروردگار تو غالب (اور) مہربان ہے۔","hi":"और निःसंदेह आपका पालनहार, निश्चय वही सबपर प्रभुत्वशाली, अत्यंत दयावान् है।"},{"a":176,"ar":"كَذَّبَ أَصْحَـٰبُ لْـَٔيْكَةِ ٱلْمُرْسَلِينَ","en":"The companions of the thicket [i.e., the people of Madyan] denied the messengers","ur":"اور بن کے رہنے والوں نے بھی پیغمبروں کو جھٹلایا","hi":"ऐका वालों ने रसूलों को झुठलाया।"},{"a":177,"ar":"إِذْ قَالَ لَهُمْ شُعَيْبٌ أَلَا تَتَّقُونَ","en":"When Shuʿayb said to them, \"Will you not fear Allāh?","ur":"جب ان سے شعیب نے کہا کہ تم ڈرتے کیوں نہیں؟","hi":"जब उनसे शुऐब ने कहा : क्या तुम डरते नहीं हो?"},{"a":178,"ar":"إِنِّى لَكُمْ رَسُولٌ أَمِينٌ","en":"Indeed, I am to you a trustworthy messenger.","ur":"میں تو تمہارا امانت دار پیغمبر ہوں","hi":"निःसंदेह मैं तुम्हारे लिए एक अमानतदार रसूल हूँ।"},{"a":179,"ar":"فَٱتَّقُوا۟ ٱللَّهَ وَأَطِيعُونِ","en":"So fear Allāh and obey me.","ur":"تو خدا سے ڈرو اور میرا کہا مانو","hi":"अतः तुम अल्लाह से डरो और मेरी बात मानो।"},{"a":180,"ar":"وَمَآ أَسْـَٔلُكُمْ عَلَيْهِ مِنْ أَجْرٍ ۖ إِنْ أَجْرِىَ إِلَّا عَلَىٰ رَبِّ ٱلْعَـٰلَمِينَ","en":"And I do not ask you for it any payment. My payment is only from the Lord of the worlds.","ur":"اور میں اس کام کا تم سے کچھ بدلہ نہیں مانگتا میرا بدلہ تو خدائے رب العالمین کے ذمے ہے","hi":"मैं इस (कार्य) पर तुमसे कोई पारिश्रमिक (बदला) नहीं माँगता, मेरा बदला तो केवल सारे संसारों के पालनहार पर है।"},{"a":181,"ar":"۞ أَوْفُوا۟ ٱلْكَيْلَ وَلَا تَكُونُوا۟ مِنَ ٱلْمُخْسِرِينَ","en":"Give full measure and do not be of those who cause loss.","ur":"(دیکھو) پیمانہ پورا بھرا کرو اور نقصان نہ کیا کرو","hi":"नाप पूरा दो और कम देने वालों में से न बनो।"},{"a":182,"ar":"وَزِنُوا۟ بِٱلْقِسْطَاسِ ٱلْمُسْتَقِيمِ","en":"And weigh with an even [i.e., honest] balance.","ur":"اور ترازو سیدھی رکھ کر تولا کرو","hi":"और सीधे तराज़ू से तोलो।"},{"a":183,"ar":"وَلَا تَبْخَسُوا۟ ٱلنَّاسَ أَشْيَآءَهُمْ وَلَا تَعْثَوْا۟ فِى ٱلْأَرْضِ مُفْسِدِينَ","en":"And do not deprive people of their due and do not commit abuse on earth, spreading corruption.","ur":"اور لوگوں کو ان کی چیزیں کم نہ دیا کرو اور ملک میں فساد نہ کرتے پھرو","hi":"और लाेगों को उनका सामान कम न दो। और धरती में उपद्रव फैलाते मत फिरो।"},{"a":184,"ar":"وَٱتَّقُوا۟ ٱلَّذِى خَلَقَكُمْ وَٱلْجِبِلَّةَ ٱلْأَوَّلِينَ","en":"And fear He who created you and the former creation.\"","ur":"اور اس سے ڈرو جس نے تم کو اور پہلی خلقت کو پیدا کیا","hi":"और उससे डरो, जिसने तुम्हें तथा पहले लोगों को पैदा किया है।"},{"a":185,"ar":"قَالُوٓا۟ إِنَّمَآ أَنتَ مِنَ ٱلْمُسَحَّرِينَ","en":"They said, \"You are only of those affected by magic.","ur":"وہ کہنے لگے کہ تم جادو زدہ ہو","hi":"उन्होंने कहा : निःसंदेह तू तो उन लोगों में से है जिनपर ताक़तवर जादू किया गया है।"},{"a":186,"ar":"وَمَآ أَنتَ إِلَّا بَشَرٌ مِّثْلُنَا وَإِن نَّظُنُّكَ لَمِنَ ٱلْكَـٰذِبِينَ","en":"You are but a man like ourselves, and indeed, we think you are among the liars.","ur":"اور تم اور کچھ نہیں ہم ہی جیسے آدمی ہو۔ اور ہمارا خیال ہے کہ تم جھوٹے ہو","hi":"और तू तो बस हमारे ही जैसा एक मनुष्य है और निःसंदेह हम तो तुझे झूठों में से समझते हैं।"},{"a":187,"ar":"فَأَسْقِطْ عَلَيْنَا كِسَفًا مِّنَ ٱلسَّمَآءِ إِن كُنتَ مِنَ ٱلصَّـٰدِقِينَ","en":"So cause to fall upon us fragments of the sky, if you should be of the truthful.\"","ur":"اور اگر سچے ہو تو ہم پر آسمان سے ایک ٹکڑا لا کر گراؤ","hi":"तो हम पर आसमान से कुछ टुकड़े गिरा दे, यदि तू सच्चों में से है।"},{"a":188,"ar":"قَالَ رَبِّىٓ أَعْلَمُ بِمَا تَعْمَلُونَ","en":"He said, \"My Lord is most knowing of what you do.\"","ur":"شعیب نے کہا کہ جو کام تم کرتے ہو میرا پروردگار اس سے خوب واقف ہے","hi":"उसने कहा : मेरा पालनहार अधिक जानने वाला है जो कुछ तुम कर रहे हो।"},{"a":189,"ar":"فَكَذَّبُوهُ فَأَخَذَهُمْ عَذَابُ يَوْمِ ٱلظُّلَّةِ ۚ إِنَّهُۥ كَانَ عَذَابَ يَوْمٍ عَظِيمٍ","en":"And they denied him, so the punishment of the day of the black cloud seized them. Indeed, it was the punishment of a terrible day.","ur":"تو ان لوگوں نے ان کو جھٹلایا، پس سائبان کے عذاب نے ان کو آ پکڑا۔ بےشک وہ بڑے (سخت) دن کا عذاب تھا","hi":"चुनाँचे उन्होंने उसे झुठला दिया। तो उन्हें छाया के दिन की यातना ने पकड़ लिया। निश्चय वह एक बड़े दिन की यातना थी।"},{"a":190,"ar":"إِنَّ فِى ذَٰلِكَ لَـَٔايَةً ۖ وَمَا كَانَ أَكْثَرُهُم مُّؤْمِنِينَ","en":"Indeed in that is a sign, but most of them were not to be believers.","ur":"اس میں یقیناً نشانی ہے۔ اور ان میں اکثر ایمان لانے والے نہیں تھے","hi":"निःसंदेह इसमें निश्चय एक बड़ी निशानी है। और उनमें से अधिकतर ईमानवाले नहीं थे।"},{"a":191,"ar":"وَإِنَّ رَبَّكَ لَهُوَ ٱلْعَزِيزُ ٱلرَّحِيمُ","en":"And indeed, your Lord - He is the Exalted in Might, the Merciful.","ur":"اور تمہارا پروردگار تو غالب (اور) مہربان ہے","hi":"और निःसंदेह आपका पालनहार, निश्चय वही सबपर प्रभुत्वशाली, अत्यंत दयावान् है।"},{"a":192,"ar":"وَإِنَّهُۥ لَتَنزِيلُ رَبِّ ٱلْعَـٰلَمِينَ","en":"And indeed, it [i.e., the Qur’ān] is the revelation of the Lord of the worlds.","ur":"اور یہ قرآن (خدائے) پروردگار عالم کا اُتارا ہوا ہے","hi":"तथा निःसंदेह, यह (क़ुरआन) निश्चय सारे संसारों के पालनहार का उतारा हुआ है।"},{"a":193,"ar":"نَزَلَ بِهِ ٱلرُّوحُ ٱلْأَمِينُ","en":"The Trustworthy Spirit [i.e., Gabriel] has brought it down","ur":"اس کو امانت دار فرشتہ لے کر اُترا ہے","hi":"इसे रूह़ुल-अमीन (अत्यंत विश्वसनीय फ़रिश्ता) लेकर उतरा है।"},{"a":194,"ar":"عَلَىٰ قَلْبِكَ لِتَكُونَ مِنَ ٱلْمُنذِرِينَ","en":"Upon your heart, [O Muḥammad] - that you may be of the warners -","ur":"(یعنی اس نے) تمہارے دل پر (القا) کیا ہے تاکہ (لوگوں کو) نصیحت کرتے رہو","hi":"आपके दिल पर, ताकि आप सावधान करने वालों में से हो जाएँ।"},{"a":195,"ar":"بِلِسَانٍ عَرَبِىٍّ مُّبِينٍ","en":"In a clear Arabic language.","ur":"اور (القا بھی) فصیح عربی زبان میں (کیا ہے)","hi":"स्पष्ट अरबी भाषा में।"},{"a":196,"ar":"وَإِنَّهُۥ لَفِى زُبُرِ ٱلْأَوَّلِينَ","en":"And indeed, it is [mentioned] in the scriptures of former peoples.","ur":"اور اس کی خبر پہلے پیغمبروں کی کتابوں میں (لکھی ہوئی) ہے","hi":"तथा निःसंदेह यह निश्चित रूप से पहले लोगों की पुस्तकों में मौजूद है।"},{"a":197,"ar":"أَوَلَمْ يَكُن لَّهُمْ ءَايَةً أَن يَعْلَمَهُۥ عُلَمَـٰٓؤُا۟ بَنِىٓ إِسْرَٰٓءِيلَ","en":"And has it not been a sign to them that it is recognized by the scholars of the Children of Israel?","ur":"کیا ان کے لئے یہ سند نہیں ہے کہ علمائے بنی اسرائیل اس (بات) کو جانتے ہیں","hi":"क्या उनके लिए यह एक निशानी न थी है कि इसे बनी इसराईल के विद्वान जानते हैं।"},{"a":198,"ar":"وَلَوْ نَزَّلْنَـٰهُ عَلَىٰ بَعْضِ ٱلْأَعْجَمِينَ","en":"And even if We had revealed it to one among the foreigners","ur":"اور اگر ہم اس کو کسی غیر اہل زبان پر اُتارتے","hi":"और यदि हम इसे ग़ैर-अरब लोगों में से किसी पर उतार देते।"},{"a":199,"ar":"فَقَرَأَهُۥ عَلَيْهِم مَّا كَانُوا۟ بِهِۦ مُؤْمِنِينَ","en":"And he had recited it to them [perfectly], they would [still] not have been believers in it.","ur":"اور وہ اسے ان (لوگوں کو) پڑھ کر سناتا تو یہ اسے (کبھی) نہ مانتے","hi":"फिर वह इसे उनके सामने पढ़ता, तो भी वे उसपर ईमान लाने वाले न होते।"},{"a":200,"ar":"كَذَٰلِكَ سَلَكْنَـٰهُ فِى قُلُوبِ ٱلْمُجْرِمِينَ","en":"Thus have We inserted it [i.e., disbelief] into the hearts of the criminals.","ur":"اسی طرح ہم نے انکار کو گنہگاروں کے دلوں میں داخل کردیا","hi":"इसी प्रकार हमने इसे अपराधियों के हृदयों में प्रवेश कर दिया।"},{"a":201,"ar":"لَا يُؤْمِنُونَ بِهِۦ حَتَّىٰ يَرَوُا۟ ٱلْعَذَابَ ٱلْأَلِيمَ","en":"They will not believe in it until they see the painful punishment.","ur":"وہ جب تک درد دینے والا عذاب نہ دیکھ لیں گے، اس کو نہیں مانیں گے","hi":"वे उसपर ईमान नहीं लाएँगे, यहाँ तक कि वे दर्दनाक यातना देख लें।"},{"a":202,"ar":"فَيَأْتِيَهُم بَغْتَةً وَهُمْ لَا يَشْعُرُونَ","en":"And it will come to them suddenly while they perceive [it] not.","ur":"وہ ان پر ناگہاں آ واقع ہوگا اور انہیں خبر بھی نہ ہوگی","hi":"तो वह उनपर अचानक आ पड़े और वे सोचते भी न हों।"},{"a":203,"ar":"فَيَقُولُوا۟ هَلْ نَحْنُ مُنظَرُونَ","en":"And they will say, \"May we be reprieved?\"","ur":"اس وقت کہیں گے کیا ہمیں ملہت ملے گی؟","hi":"फिर वे कहें : क्या हम मोहलत दिए जाने वाले हैं"},{"a":204,"ar":"أَفَبِعَذَابِنَا يَسْتَعْجِلُونَ","en":"So for Our punishment are they impatient?","ur":"تو کیا یہ ہمارے عذاب کو جلدی طلب کر رہے ہیں","hi":"तो क्या वे हमारी यातना के लिए जल्दी मचा रहे हैं?"},{"a":205,"ar":"أَفَرَءَيْتَ إِن مَّتَّعْنَـٰهُمْ سِنِينَ","en":"Then have you considered if We gave them enjoyment for years","ur":"بھلا دیکھو تو اگر ہم ان کو برسوں فائدے دیتے رہے","hi":"तो क्या आपने विचार किया यदि हम इन्हें कुछ वर्षों तक लाभ दें।"},{"a":206,"ar":"ثُمَّ جَآءَهُم مَّا كَانُوا۟ يُوعَدُونَ","en":"And then there came to them that which they were promised?","ur":"پھر ان پر وہ (عذاب) آ واقع ہو جس کا تم سے وعدہ کیا جاتا ہے","hi":"फिर उनपर वह (यातना) आ जाए, जिसका उनसे वादा किया जाता था।"},{"a":207,"ar":"مَآ أَغْنَىٰ عَنْهُم مَّا كَانُوا۟ يُمَتَّعُونَ","en":"They would not be availed by the enjoyment with which they were provided.","ur":"تو جو فائدے یہ اٹھاتے رہے ان کے کس کام آئیں گے","hi":"तो उन्हें जो लाभ दिया जाता था, वह उनके किस काम आएगा?"},{"a":208,"ar":"وَمَآ أَهْلَكْنَا مِن قَرْيَةٍ إِلَّا لَهَا مُنذِرُونَ","en":"And We did not destroy any city except that it had warners","ur":"اور ہم نے کوئی بستی ہلاک نہیں کی مگر اس کے لئے نصیحت کرنے والے (پہلے بھیج دیتے) تھے","hi":"और हमने किसी बस्ती को विनष्ट नहीं किया, परंतु उसके लिए कई सावधान करने वाले थे।"},{"a":209,"ar":"ذِكْرَىٰ وَمَا كُنَّا ظَـٰلِمِينَ","en":"As a reminder; and never have We been unjust.","ur":"نصیحت کردیں اور ہم ظالم نہیں ہیں","hi":"याद दिलाने के लिए। और हम अत्याचारी नहीं थे।"},{"a":210,"ar":"وَمَا تَنَزَّلَتْ بِهِ ٱلشَّيَـٰطِينُ","en":"And the devils have not brought it [i.e., the revelation] down.","ur":"اور اس (قرآن) کو شیطان لے کر نازل نہیں ہوئے","hi":"तथा इस (क़ुरआन) को लेकर शैतान नहीं उतरे।"},{"a":211,"ar":"وَمَا يَنۢبَغِى لَهُمْ وَمَا يَسْتَطِيعُونَ","en":"It is not allowable for them, nor would they be able.","ur":"یہ کام نہ تو ان کو سزاوار ہے اور نہ وہ اس کی طاقت رکھتے ہیں","hi":"और न यह उनके योग्य है, और न वे ऐसा कर सकते हैं।"},{"a":212,"ar":"إِنَّهُمْ عَنِ ٱلسَّمْعِ لَمَعْزُولُونَ","en":"Indeed they, from [its] hearing, are removed.","ur":"وہ (آسمانی باتوں) کے سننے (کے مقامات) سے الگ کر دیئے گئے ہیں","hi":"निःसंदेह वे तो (इसके) सुनने ही से अलग कर दिए गए हैं।"},{"a":213,"ar":"فَلَا تَدْعُ مَعَ ٱللَّهِ إِلَـٰهًا ءَاخَرَ فَتَكُونَ مِنَ ٱلْمُعَذَّبِينَ","en":"So do not invoke with Allāh another deity and [thus] be among the punished.","ur":"تو خدا کے سوا کسی اور معبود کو مت پکارنا، ورنہ تم کو عذاب دیا جائے گا","hi":"अतः आप अल्लाह के साथ किसी अन्य पूज्य को न पुकारें, अन्यथा आप दंड पाने वालों में हो जाएँगे।"},{"a":214,"ar":"وَأَنذِرْ عَشِيرَتَكَ ٱلْأَقْرَبِينَ","en":"And warn, [O Muḥammad], your closest kindred.","ur":"اور اپنے قریب کے رشتہ داروں کو ڈر سنا دو","hi":"और आप अपने निकटतम रिश्तेदारों को डराएँ।"},{"a":215,"ar":"وَٱخْفِضْ جَنَاحَكَ لِمَنِ ٱتَّبَعَكَ مِنَ ٱلْمُؤْمِنِينَ","en":"And lower your wing [i.e., show kindness] to those who follow you of the believers.","ur":"اور جو مومن تمہارے پیرو ہوگئے ہیں ان سے متواضع پیش آؤ","hi":"और ईमान वालों में से जो आपका अनुसरण करे, उसके लिए अपना बाज़ू झुका दें।"},{"a":216,"ar":"فَإِنْ عَصَوْكَ فَقُلْ إِنِّى بَرِىٓءٌ مِّمَّا تَعْمَلُونَ","en":"And if they disobey you, then say, \"Indeed, I am disassociated from what you are doing.\"","ur":"پھر اگر لوگ تمہاری نافرمانی کریں تو کہہ دو کہ میں تمہارے اعمال سے بےتعلق ہوں","hi":"फि यदि वे आपकी अवज्ञा करें, तो आप कह दें कि तुम जो कुछ कर रहे हो उसकी ज़िम्मेदारी से मैं बरी हूँ।"},{"a":217,"ar":"وَتَوَكَّلْ عَلَى ٱلْعَزِيزِ ٱلرَّحِيمِ","en":"And rely upon the Exalted in Might, the Merciful,","ur":"اور (خدائے) غالب اور مہربان پر بھروسا رکھو","hi":"तथा उस सबपर प्रभुत्वशाली, अत्यंत दयावान् पर भरोसा करें।"},{"a":218,"ar":"ٱلَّذِى يَرَىٰكَ حِينَ تَقُومُ","en":"Who sees you when you arise","ur":"جو تم کو جب تم (تہجد) کے وقت اُٹھتے ہو دیکھتا ہے","hi":"जो आपको देखता है, जब आप खड़े होते हैं।"},{"a":219,"ar":"وَتَقَلُّبَكَ فِى ٱلسَّـٰجِدِينَ","en":"And your movement among those who prostrate.","ur":"اور نمازیوں میں تمہارے پھرنے کو بھی","hi":"और सजदा करने वालों में आपके फिरने को भी।"},{"a":220,"ar":"إِنَّهُۥ هُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ","en":"Indeed, He is the Hearing, the Knowing.","ur":"بےشک وہ سننے اور جاننے والا ہے","hi":"निःसंदेह वही सब कुछ सुनने वाला, सब कुछ जानने वाला है।"},{"a":221,"ar":"هَلْ أُنَبِّئُكُمْ عَلَىٰ مَن تَنَزَّلُ ٱلشَّيَـٰطِينُ","en":"Shall I inform you upon whom the devils descend?","ur":"(اچھا) میں تمیں بتاؤں کہ شیطان کس پر اُترتے ہیں","hi":"क्या मैं आपको बताऊँ कि शैतान किस पर उतरते हैं?"},{"a":222,"ar":"تَنَزَّلُ عَلَىٰ كُلِّ أَفَّاكٍ أَثِيمٍ","en":"They descend upon every sinful liar.","ur":"ہر جھوٹے گنہگار پر اُترتے ہیں","hi":"वे हर बड़े झूठे और बड़े पापी पर उतरते हैं।"},{"a":223,"ar":"يُلْقُونَ ٱلسَّمْعَ وَأَكْثَرُهُمْ كَـٰذِبُونَ","en":"They pass on what is heard, and most of them are liars.","ur":"جو سنی ہوئی بات (اس کے کام میں) لا ڈالتے ہیں اور وہ اکثر جھوٹے ہیں","hi":"वे सुनी हुई बात को (काहिनों तक) पहुँचा देते हैं, और उनमें से अधिकतर झूठे हैं।"},{"a":224,"ar":"وَٱلشُّعَرَآءُ يَتَّبِعُهُمُ ٱلْغَاوُۥنَ","en":"And the poets - [only] the deviators follow them;","ur":"اور شاعروں کی پیروی گمراہ لوگ کیا کرتے ہیں","hi":"और कवि लोग, उनके पीछे भटके हुए लोग ही चलते हैं।"},{"a":225,"ar":"أَلَمْ تَرَ أَنَّهُمْ فِى كُلِّ وَادٍ يَهِيمُونَ","en":"Do you not see that in every valley they roam","ur":"کیا تم نے نہیں دیکھا کہ وہ ہر وادی میں سر مارتے پھرتے ہیں","hi":"क्या आपने नहीं देखा कि वे प्रत्येक वादी में भटकते फिरते हैं।"},{"a":226,"ar":"وَأَنَّهُمْ يَقُولُونَ مَا لَا يَفْعَلُونَ","en":"And that they say what they do not do? -","ur":"اور کہتے وہ ہیں جو کرتے نہیں","hi":"और यह कि निःसंदेह ऐसी बात कहते हैं, जो करते नहीं।"},{"a":227,"ar":"إِلَّا ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ وَذَكَرُوا۟ ٱللَّهَ كَثِيرًا وَٱنتَصَرُوا۟ مِنۢ بَعْدِ مَا ظُلِمُوا۟ ۗ وَسَيَعْلَمُ ٱلَّذِينَ ظَلَمُوٓا۟ أَىَّ مُنقَلَبٍ يَنقَلِبُونَ","en":"Except those [poets] who believe and do righteous deeds and remember Allāh often and defend [the Muslims] after they were wronged. And those who have wronged are going to know to what [kind of] return they will be returned.","ur":"مگر جو لوگ ایمان لائے اور نیک کام کئے اور خدا کو بہت یاد کرتے رہے اور اپنے اوپر ظلم ہونے کے بعد انتقام لیا اور ظالم عنقریب جان لیں گے کہ کون سی جگہ لوٹ کر جاتے ہیں","hi":"सिवाय उन (कवियों) के, जो ईमान लाए, और अच्छे कर्म किए और अल्लाह को बहुत याद किया तथा बदला लिया, इसके बाद कि उनके ऊपर ज़ुल्म किया गया। तथा वे लोग, जिन्होंने अत्याचार किया, शीघ्र ही जान लेंगे कि वे किस जगह लौटकर जाएँगे।"}],"tlx":{"hi":"अश-शुअरा","ur":"الشعراء"}};
